window.EP01 = {"title": "RED LEDGER 第1話「払わねえよ。」絵コンテ", "total": 1330.0, "seqs": [{"key": "s1", "label": "アバン①　夜市", "range": ["00:00", "01:00"], "start": 0.0, "end": 60.0, "first": 1, "last": 15, "drawn": true}, {"key": "s2", "label": "アバン②　追跡〜タイトル", "range": ["01:00", "03:10"], "start": 60.0, "end": 190.0, "first": 16, "last": 32, "drawn": true}, {"key": "t1", "label": "Aパート〜Bパート前半", "range": ["03:10", "12:40"], "start": 190.0, "end": 760.0, "first": 33, "last": 129, "drawn": false}, {"key": "s3", "label": "Bパート　覚醒", "range": ["12:40", "15:00"], "start": 760.0, "end": 900.0, "first": 130, "last": 151, "drawn": true}, {"key": "t2", "label": "Bパート後半〜Cパート", "range": ["15:00", "21:10"], "start": 900.0, "end": 1270.0, "first": 152, "last": 215, "drawn": false}, {"key": "s4", "label": "タグ・次回予告", "range": ["21:10", "22:10"], "start": 1270.0, "end": 1330.0, "first": 216, "last": 225, "drawn": true}], "cuts": [{"no": 1, "seq": "s1", "local": 1, "scene": "底帳・夜市「肋骨通り」・夜", "start": 0.0, "sec": 6.0, "frames": ["s1-c01a.svg", "s1-c01b.svg"], "camera": "BLACK(2+0)→F.I.／真俯瞰からゆっくりT.U.（クレーン降下）", "shot": "真俯瞰 ELS", "picture": "黒画面。F.I.すると真上からの俯瞰：死んだ神の白い肋骨が画面の四方からカメラへ弧を描いてせり上がり、その内側に提灯・配線・違法建築が蜂の巣状に何層も積み重なる。最深部に夜市の灯り。都市カネグラ最下層・底帳。", "action": "黒の2秒は動きなし。F.I.後、井戸の底（夜市）へ向かってゆっくり降りていく。提灯の列がわずかに揺れる。ロゴ・テロップ一切なし。", "dialogue": "", "dialogue_en": "", "sound": "【SKIP-PROOF】黒に心音のような低い鐘1つ→一拍。F.I.で夜市のざわめき（遠く）。カット尻、頂から鐘①（重い一打）。"}, {"no": 2, "seq": "s1", "local": 2, "scene": "底帳・夜市「肋骨通り」・夜", "start": 6.0, "sec": 8.0, "frames": ["s1-c02a.svg", "s1-c02b.svg"], "camera": "FIX→TILT UP（群衆の視線を追って肋骨の上へ）", "shot": "LS→あおり", "picture": "地上の夜市。屋台の天幕、提灯の列、肋骨の柱。手前に大きな提灯。群衆が鐘で一斉に静止し上を見る。TILT UP後：肋骨が大聖堂のように頭上で収束し、骨に張りついたバラック、電線、はるか上に頂の白い光。画面右に公開格付け掲示板の端。", "action": "カット頭でざわめきが止まり全員が静止（コマ止めではなく芝居で止める）。2秒後TILT UP開始、鐘②③に合わせて頂の光が脈打つ（音の輪がPAN下へ広がる）。", "dialogue": "", "dialogue_en": "", "sound": "SE：ざわめき→鐘①の余韻でカットアウト（無音に近い）。鐘②③ くっきり。"}, {"no": 3, "seq": "s1", "local": 3, "scene": "底帳・夜市「肋骨通り」・夜", "start": 14.0, "sec": 5.5, "frames": ["s1-c03a.svg", "s1-c03b.svg"], "camera": "PAN DOWN（掲示板の上段→下段、流れる文字と同速）", "shot": "MS（掲示板）", "picture": "肋骨にボルトで留められた巨大電光掲示板〈公開格付け〉。上段は大きく明るい AAA・AA の名前（九条レイジ、サカキ・ドウゲン他）。下へ行くほど文字は小さく暗く、D は読めない線の滝になる。掲示板の下に夜市の屋根と提灯。", "action": "名前と格付けが滝のように下へ流れ続ける。カメラは流れに乗ってPAN DOWNし、D の暗い帯を抜けて屋根の上で止まる。", "dialogue": "", "dialogue_en": "", "sound": "鐘④⑤⑥（遠ざかり始める）。掲示板の電子ノイズ（低いハム）。"}, {"no": 4, "seq": "s1", "local": 4, "scene": "底帳・夜市「肋骨通り」・夜", "start": 19.5, "sec": 4.5, "frames": ["s1-c04.svg"], "camera": "FIX→T.U.（告知点灯と同時、小さく速く）", "shot": "MS→BS（掲示板最上段）", "picture": "掲示板の最上段に白い告知帯が点灯。「本日　取立日〈コレクション・デイ〉」「返済不能者は担保を提出してください」英文併記。流れていた名前は押し下げられ暗くなる。", "action": "告知がパッと白く点き、縁から光の線が走る。カメラは点灯と同時にT.U.。", "dialogue": "掲示板「本日 取立日〈コレクション・デイ〉。返済不能者は担保を提出してください」", "dialogue_en": "TODAY IS COLLECTION DAY. DEFAULTERS WILL SURRENDER COLLATERAL.", "sound": "SE：点灯音（バチン）。鐘⑦⑧。"}, {"no": 5, "seq": "s1", "local": 5, "scene": "底帳・夜市「肋骨通り」・夜", "start": 24.0, "sec": 3.5, "frames": ["s1-c05.svg"], "camera": "FIX（掲示板側からの見下ろし）", "shot": "俯瞰 LS", "picture": "真上寄りの俯瞰。夜市の通りを埋める頭・肩。四隅に屋台の天幕。", "action": "群衆が一斉に自分の左手首を右手で押さえる（さざ波のように手前→奥へ伝わる）。押さえた手首の印が朱・翠・藍に淡く光る。", "dialogue": "", "dialogue_en": "", "sound": "鐘⑨。衣ずれが一斉に（ザッ）。"}, {"no": 6, "seq": "s1", "local": 6, "scene": "底帳・夜市「肋骨通り」・夜", "start": 27.5, "sec": 1.2, "frames": ["s1-c06.svg"], "camera": "FIX", "shot": "CU（手首）", "picture": "職人の太い左腕、まくった袖。手首の印（帳簿の印：輪＋取り消し線）が光り「残高 −120」。", "action": "数字がふっと浮かぶ。", "dialogue": "", "dialogue_en": "", "sound": "鐘⑩。印の点灯音（小）。"}, {"no": 7, "seq": "s1", "local": 7, "scene": "底帳・夜市「肋骨通り」・夜", "start": 28.7, "sec": 1.2, "frames": ["s1-c07.svg"], "camera": "FIX", "shot": "CU（手首）", "picture": "細い手首を斜めに。腕輪。印が光り「残高 −3,400」。", "action": "数字が浮かぶ。指がきゅっと縮む。", "dialogue": "", "dialogue_en": "", "sound": "印の点灯音（小）。"}, {"no": 8, "seq": "s1", "local": 8, "scene": "底帳・夜市「肋骨通り」・夜", "start": 29.9, "sec": 1.2, "frames": ["s1-c08.svg"], "camera": "FIX", "shot": "CU（手首）", "picture": "老人の皺だらけの手、手のひら上向き、手首に包帯。印が光り「残高 −18」。", "action": "数字が浮かぶ。", "dialogue": "", "dialogue_en": "", "sound": "鐘⑪。印の点灯音（小）。"}, {"no": 9, "seq": "s1", "local": 9, "scene": "底帳・夜市「肋骨通り」・夜", "start": 31.1, "sec": 2.4, "frames": ["s1-c09.svg"], "camera": "手持ち（ブレ）", "shot": "CU（手首）", "picture": "若者の左手首を自分の右手が握りしめる。印が光り「残高 −9,999」。", "action": "手首が小刻みに震える（作画でブレ線＋画面も微振動）。数字がわずかに二重にブレる。", "dialogue": "", "dialogue_en": "", "sound": "鐘⑫。息を呑む音。"}, {"no": 10, "seq": "s1", "local": 10, "scene": "底帳・夜市「肋骨通り」・夜", "start": 33.5, "sec": 6.5, "frames": ["s1-c10.svg"], "camera": "FIX→ゆっくりT.U.", "shot": "BS", "picture": "麺屋台の湯気と提灯を背に、頭巾の屋台の女。手前に持ち上げた自分の手首（ボケ）。", "action": "女は手首の数字を見下ろし、目を伏せたまま小さく息を吐く。台詞後、まぶたを閉じる。", "dialogue": "屋台の女「……今月も、足りない」", "dialogue_en": "...Short again this month.", "sound": "鐘⑬（最後の一打、遠くかすか）。鍋の煮える音が戻りかける。"}, {"no": 11, "seq": "s1", "local": 11, "scene": "底帳・夜市「肋骨通り」・広場・夜", "start": 40.0, "sec": 5.0, "frames": ["s1-c11a.svg", "s1-c11b.svg"], "camera": "群衆の背中ナメ→T.U.（輪の中心へ）", "shot": "LS→FS", "picture": "広場。延滞者の手配書が重ね貼りされた壁、提灯の列、肋骨の柱。群衆が輪になって遠巻きに見ている。中心に取立人（黒い長コート、立ち襟、制帽、象牙色の長方形の半仮面・横一本のスリット、印は黒）。その前に膝をつかされたギターの路上歌い手（ぼさぼさ髪、縞のマフラー）。T.U.後、下手に取立人が見下ろし、上手に歌い手が見上げる。", "action": "取立人は微動だにせず宣告する。歌い手はギターを抱えたまま膝立ちで後ずさりしかける。", "dialogue": "取立人「担保：〈声〉。期日超過。執行する」", "dialogue_en": "Collateral: voice. Payment overdue. Executing.", "sound": "BGMなし。群衆のかすかな囁き。"}, {"no": 12, "seq": "s1", "local": 12, "scene": "底帳・夜市「肋骨通り」・広場・夜", "start": 45.0, "sec": 2.5, "frames": ["s1-c12.svg"], "camera": "FIX（取立人の肩ナメ）", "shot": "BS 俯瞰気味", "picture": "取立人の黒い肩を手前に大きくナメて、見上げる歌い手。眉が上がり目を見開く。ギターのネックが画面を斜めに横切る。", "action": "歌い手が片手を上げてすがる。汗。", "dialogue": "歌い手「待ってくれ、明日、明日には——」", "dialogue_en": "Wait, tomorrow — I'll have it tomorrow —", "sound": ""}, {"no": 13, "seq": "s1", "local": 13, "scene": "底帳・夜市「肋骨通り」・広場・夜", "start": 47.5, "sec": 3.5, "frames": ["s1-c13a.svg", "s1-c13b.svg"], "camera": "FIX（真横）", "shot": "CU", "picture": "真横。手袋の長い人差し指が歌い手の喉に一本、触れる。→指先から細い光の糸が伸び、帳簿の頁のような罫線入りの光の帯が喉から引き抜かれていく（帯のまわりに音符の残光）。", "action": "指が触れる（1+0）。手を引くと、光の帯がずるりと喉から引き出され、手の方へ流れる。歌い手の台詞の尻が叫びに変わる。", "dialogue": "", "dialogue_en": "", "sound": "SE：触れる瞬間のチッという高音→引き抜く糸の擦過音。歌い手の叫び（OFF気味）が始まる。"}, {"no": 14, "seq": "s1", "local": 14, "scene": "底帳・夜市「肋骨通り」・広場・夜", "start": 51.0, "sec": 4.5, "frames": ["s1-c14a.svg", "s1-c14b.svg"], "camera": "同ポジ、ゆっくりT.U.", "shot": "ECU（顔）", "picture": "歌い手の顔の超アップ。口を大きく開けて叫んでいる。→カット途中で音だけが消える。画は同じ、叫ぶ口だけが動き続ける。目は見開かれ、自分の声がないことに気づく。", "action": "叫び（1+0）→“ブツッ”で音響カット。以降3秒以上、完全無音のまま口だけが叫び続け、カメラは寄り続ける（観客もこの無音を体験する＝世界のルールの説明）。", "dialogue": "", "dialogue_en": "", "sound": "SE：叫び→1秒で“ブツッ”と切れる。以降 完全無音（環境音・BGMともゼロ）。"}, {"no": 15, "seq": "s1", "local": 15, "scene": "底帳・夜市「肋骨通り」・広場・夜", "start": 55.5, "sec": 4.5, "frames": ["s1-c15a.svg", "s1-c15b.svg"], "camera": "FIX→T.B.（広場の全景へ）", "shot": "MS→LS", "picture": "取立人のMS。光の帯を小さな帳簿に挟み、手袋の手で閉じる。→T.B.して広場の全景：取立人は背を向けて下手へ去る。中央に、ギターを落とし喉を押さえてうずくまる歌い手。輪の群衆は皆、顔をそむけている。", "action": "帳簿がパタンと閉じる（その音だけが戻る）→「完済」。T.B.の間に取立人は下手へフレームアウト。誰も動かない、誰も止めない。歌い手の肩だけが震えている。S1終わり（次のS2頭で陶器の割れる音）。", "dialogue": "取立人「完済」", "dialogue_en": "Paid in full.", "sound": "無音→帳簿を閉じる「パタン」だけが戻る→「完済」。その後も環境音は戻さず静寂のまま、次カット（S2）頭の陶器の割れる音へ。"}, {"no": 16, "seq": "s2", "local": 1, "scene": "底帳・夜市・屋台街・夜", "start": 60.0, "sec": 6.0, "frames": ["s2-c01a.svg", "s2-c01b.svg"], "camera": "FIX→SHAKE", "shot": "LS", "picture": "広場の無音を引きずった屋台街。客は固まったまま。右手中景の天幕が内側から膨らみ、陶器の破片が弾ける。", "action": "(a)無音1秒→破砕音で画面ブレ。(b)天幕を突き破ってジンが空中へ、カメラ前に飛び込む。破片・布が四散、客がしゃがむ。", "dialogue": "ジン（OFF）「どいてどいてどいて！ 熱いの通りまーす！！」", "dialogue_en": "Jin (OFF): \"Move, move, move! Hot noodles coming through!!\"", "sound": "SE：陶器が派手に割れる→天幕が裂ける／BGM：軽快なブレイクビーツ IN（破砕音の頭で）"}, {"no": 17, "seq": "s2", "local": 2, "scene": "底帳・夜市・屋台街・夜", "start": 66.0, "sec": 8.0, "frames": ["s2-c02a.svg"], "camera": "FOLLOW（後退移動）", "shot": "FS 正面", "picture": "ジン正面走り。右手にどんぶり五段、左腕は手首から肘まで赤い印。左右の客が飛びのく。奥に見習い二人。", "action": "ジンは軽いステップで客の間を縫う。どんぶりは揺れない。奥の見習いが小さく追ってくる。", "dialogue": "", "dialogue_en": "", "sound": "BGM続く／SE：足音・客の悲鳴・屋台の皿の音"}, {"no": 18, "seq": "s2", "local": 3, "scene": "底帳・夜市・屋台街・夜", "start": 74.0, "sec": 9.0, "frames": ["s2-c03a.svg", "s2-c03b.svg"], "camera": "PAN FOLLOW（背景流し）", "shot": "MS→BS", "picture": "(a)灰色の作業服の見習いA・B、手首に携帯スキャナー。Aがジンを指さして怒鳴る。(b)ジンBS、振り返ってアカンベー。", "action": "(a)見習い二人が画面右へ全力疾走。(b)ジンは前を向かずに後ろ走り気味、ウインク＋舌。", "dialogue": "見習いA「止まれ！ 印を照会させろ！」／ジン「やだね！ 配達中だっつってんだろ！」", "dialogue_en": "Apprentice A: \"Stop! Let us scan your mark!\" / Jin: \"No way! I'm on a delivery, can't you see?!\"", "sound": "SE：見習いの靴音・息切れ"}, {"no": 19, "seq": "s2", "local": 4, "scene": "底帳・夜市・屋台街・夜", "start": 83.0, "sec": 10.0, "frames": ["s2-c04a.svg", "s2-c04b.svg"], "camera": "O.S.→CU（インサート）", "shot": "MS／CU", "picture": "(a)見習いB越し、スキャナーの照準光がジンの赤い左手首を捉える。(b)スキャナー画面のCU「ERROR」「残高：計測不能」、煙と火花、Bの驚き顔。", "action": "(a)照準ブラケットが赤い手首にロック。(b)画面がグリッチ、筐体から煙。Bの目が点。", "dialogue": "スキャナー「ピピピ——エラー。エラー。残高：計測不能」／見習いB「またコイツだ！ 照会機が壊れる！」", "dialogue_en": "Scanner: \"Beep-beep — Error. Error. Balance: unmeasurable.\" / Apprentice B: \"Him again! He breaks the scanner!\"", "sound": "SE：電子音ピピピ→エラーブザー→ボフッ（煙）"}, {"no": 20, "seq": "s2", "local": 5, "scene": "底帳・夜市・屋台街・夜", "start": 93.0, "sec": 8.0, "frames": ["s2-c05a.svg", "s2-c05b.svg"], "camera": "PAN →（右上へ）／あおり", "shot": "LS→FS", "picture": "(a)横位置の大ロング。段々の屋台屋根をジンが三段跳び、下で見習いが見上げる。(b)あおり、屋上から洗濯ロープへ跳び、首の手ぬぐいを引っかける。", "action": "(a)ホップ・ステップ・ジャンプで一段ずつ上がる（点線で軌跡）。(b)空中で手ぬぐいをロープに回す。", "dialogue": "", "dialogue_en": "", "sound": "SE：トタン屋根を踏む音×3／BGM：ブレイク"}, {"no": 21, "seq": "s2", "local": 6, "scene": "底帳・夜市・屋台街・夜", "start": 101.0, "sec": 12.0, "frames": ["s2-c06a.svg", "s2-c06b.svg"], "camera": "FIX／BS", "shot": "FS→BS", "picture": "(a)ロープを滑り降りるジン、窓辺の老人へ一番上のどんぶりを滑らせる。(b)老人BS、真顔でどんぶりを受け取る。ジンは右へフレームアウト。", "action": "(a)滑りながら一杯だけ正確にパス。(b)老人は眉一つ動かさない。ジン「だよな！」で笑って抜ける。", "dialogue": "ジン「じいさん、ネギ多め！ 代金はツケでいい！」／老人「お前にツケる奴がいるか」／ジン「だよな！」", "dialogue_en": "Jin: \"Gramps, extra scallions! Put it on my tab!\" / Old man: \"Who'd ever give YOU a tab?\" / Jin: \"Fair!\"", "sound": "SE：ロープの擦れる音シュルル、どんぶりを置くコトン"}, {"no": 22, "seq": "s2", "local": 7, "scene": "底帳・夜市・屋台街・夜", "start": 113.0, "sec": 12.0, "frames": ["s2-c07a.svg", "s2-c07b.svg"], "camera": "STOP MOTION（止め）→POP", "shot": "FS", "picture": "(a)空中で逆さまのジンが静止（画面全体をモノトーン寄りに、太い黒枠）。(b)格付けカードがポップアップ「赤羽ジン 16歳／AKABA JIN, 16／格付け RATING：ZERO」。ジンはピース。", "action": "止めは完全静止。カードは画面右からスライドイン＋バウンド。モノローグの間、背景の見習いも空中で固まったまま。", "dialogue": "テロップ「赤羽ジン　16歳　格付け：ZERO」／ジン（モノローグ）「どうも。この街でいちばん“価値のない”男です」", "dialogue_en": "On-screen: AKABA JIN, 16. RATING: ZERO / Jin (V.O.): \"Hi. I'm the least valuable person in this city.\"", "sound": "SE：レコードスクラッチでBGM一時停止→カードのポップ音／モノローグ後にBGM再開"}, {"no": 23, "seq": "s2", "local": 8, "scene": "底帳・夜市・屋台街・夜", "start": 125.0, "sec": 10.0, "frames": ["s2-c08a.svg", "s2-c08b.svg"], "camera": "FIX／FS", "shot": "FS", "picture": "(a)ストップ解除、ジンが見習いAの頭（帽子）を踏み台にして跳ぶ。Bは口あんぐり。(b)袋小路の入口に片膝着地、どんぶりを高々と掲げる。一滴もこぼれていない。", "action": "(a)Aの帽子がへこむ。(b)着地の土ぼこり、どんぶりにキラリ。ジンはドヤ顔。", "dialogue": "ジン「よっしゃ、汁ゼロ！」", "dialogue_en": "Jin: \"Yes! Zero spillage!\"", "sound": "SE：踏みつけ音ギュム、見習いA「ぶっ」、着地音タン"}, {"no": 24, "seq": "s2", "local": 9, "scene": "底帳・袋小路・夜", "start": 135.0, "sec": 7.0, "frames": ["s2-c09a.svg", "s2-c09b.svg"], "camera": "FIX→切り返し", "shot": "LS→O.S.", "picture": "(a)背中のジン、正面は高い壁の行き止まり。(b)切り返し、ジン肩越しに路地の入口。見習い二人が立ち止まり、一歩下がる。", "action": "(a)ジンが壁を見上げて振り返る。(b)見習いは追ってこない。むしろ後ずさり。", "dialogue": "ジン「……なんだよ。急に遠慮して」", "dialogue_en": "Jin: \"...What? Suddenly shy?\"", "sound": "BGM：カットアウト（無音に近い路地の環境音のみ）"}, {"no": 25, "seq": "s2", "local": 10, "scene": "底帳・袋小路・夜", "start": 142.0, "sec": 4.0, "frames": ["s2-c10a.svg"], "camera": "FIX", "shot": "CU", "picture": "見習いAの顔CU。汗、震え、目はジンの頭上（壁の上）を見ている。", "action": "口がわなわな震える。目線は上に固定。", "dialogue": "見習いA「……ニ、ニルさん」", "dialogue_en": "Apprentice A: \"...M-Mister Nil.\"", "sound": "SE：遠くの鐘の余韻"}, {"no": 26, "seq": "s2", "local": 11, "scene": "底帳・袋小路・夜", "start": 146.0, "sec": 6.0, "frames": ["s2-c11a.svg"], "camera": "T.U.（ゆっくり）", "shot": "極端なあおり LS→FS", "picture": "ジンの後頭部越し、行き止まりの壁の上に取立人ニル。平たいつばの制帽、刈り込んだ灰色の髪、高い立ち襟の黒いフロックコート。長方形の象牙色の仮面（閉じた帳簿の表紙、横一本のスリット、片側に綴じ目）。腕に灰色の鎖が巻かれている（使わない）。", "action": "ニルは動かない。T.U.で壁上へ寄る。コートの裾だけがわずかに揺れる。", "dialogue": "", "dialogue_en": "", "sound": "SE：空気の圧が変わる低いうなり（ここから持続）"}, {"no": 27, "seq": "s2", "local": 12, "scene": "底帳・袋小路・夜", "start": 152.0, "sec": 5.0, "frames": ["s2-c12a.svg"], "camera": "FIX", "shot": "FS", "picture": "ニルが音もなく壁から降りる。コートが翼のように広がる。手前でジンが振り向き、目を見開く。", "action": "落下は着地音なし（土ぼこりだけ）。ジンの振り向きと着地を同時に。", "dialogue": "", "dialogue_en": "", "sound": "SE：なし（低いうなりのみ）"}, {"no": 28, "seq": "s2", "local": 13, "scene": "底帳・袋小路・夜", "start": 157.0, "sec": 8.0, "frames": ["s2-c13a.svg", "s2-c13b.svg"], "camera": "FIX（切り返し）", "shot": "BS", "picture": "(a)ニルBS、あおり。仮面が少し傾き、ジンの左腕を見下ろす。長い指の手袋。(b)ジンBS、左腕をさっと背中に隠し、目をそらして真顔で嘘をつく。", "action": "(a)スリットの奥は見えない。(b)ジンの汗、目線を外す。コメディの最後の一拍。", "dialogue": "ニル「赤い腕。……赤羽の息子か」／ジン「……人違いです。俺、青羽です」", "dialogue_en": "Nil: \"A red arm... Akaba's son.\" / Jin: \"...Wrong guy. I'm Aoba.\"", "sound": "SE：低いうなり"}, {"no": 29, "seq": "s2", "local": 14, "scene": "底帳・袋小路・夜", "start": 165.0, "sec": 6.0, "frames": ["s2-c14a.svg", "s2-c14b.svg"], "camera": "FIX／ECU", "shot": "地面すれすれ／ECU", "picture": "(a)ニルのブーツが一歩、手前に大きく。奥でジンの足が後ずさり。(b)ジンの左前腕ECU、赤い印に「−∞」、印がドクンと脈打つ（赤い波紋）。", "action": "(a)一歩だけ。(b)赤い印が2回脈打ち、光が強まる。", "dialogue": "", "dialogue_en": "", "sound": "SE：ブーツの音コツ→心音ドクン、ドクン"}, {"no": 30, "seq": "s2", "local": 15, "scene": "底帳・袋小路・夜", "start": 171.0, "sec": 4.0, "frames": ["s2-c15a.svg"], "camera": "FIX（BG白抜き）", "shot": "CU", "picture": "ジンの顔CU。背景が白く抜け、帳簿の罫線だけが残る。宙に赤いインクが一滴。", "action": "ジンの目が見開かれる。周囲の音が全部消え、声だけが聞こえる演出。", "dialogue": "？？？（子どもの声）「……みぃつけた」／ジン「……え？」", "dialogue_en": "??? (child's voice): \"...Found you.\" / Jin: \"...Huh?\"", "sound": "MA：環境音OFF、子どものささやき（ジンの耳元・ドライ）"}, {"no": 31, "seq": "s2", "local": 16, "scene": "底帳・袋小路・夜", "start": 175.0, "sec": 5.0, "frames": ["s2-c16a.svg", "s2-c16b.svg"], "camera": "O.S.→ECU", "shot": "O.S.／ECU", "picture": "(a)ジン越し、ニルの手袋の長い指が喉へ伸びる。(b)ジンの瞳のECUに迫る指先が映る。下段、赤い印が肘から肩へ一瞬“這い上がる”。", "action": "(b)赤い光が肩に届いた瞬間、無音のままSMASH CUT。力はまだ見せない。", "dialogue": "", "dialogue_en": "", "sound": "SE：すべての音が吸い込まれるように消える→完全無音"}, {"no": 32, "seq": "s2", "local": 17, "scene": "タイトルカード", "start": 180.0, "sec": 10.0, "frames": ["s2-c17a.svg"], "camera": "FIX", "shot": "—", "picture": "黒地に帳簿の罫線。赤いインクが罫線を伝って広がり、文字になる「RED LEDGER／赤い帳簿」。右下に赤い判子。", "action": "インクが罫線をにじみながら走り、ロゴが完成（約6秒）→判子が押される（8秒目）→黒みのまま本編へ。", "dialogue": "", "dialogue_en": "On-screen: RED LEDGER", "sound": "SE：インクがにじむ音→判子を押す音、一発／第1話はOPなし"}, {"no": 33, "seq": "t1", "local": 1, "scene": "底帳・麺屋台「霧島」・裏の物置・朝", "start": 190.0, "sec": 9.0, "frames": [], "camera": "PAN DOWN", "shot": "LS 俯瞰→LS", "picture": "底帳の朝。画面上端に死んだ神の肋骨の白い弧、その下に違法建築の谷。PAN DOWN して路地の底の麺屋台「霧島」。暖簾はまだ畳まれ、屋台の煙突から湯気が細く昇る。", "action": "骨の隙間から朝の光が斜めに差し、湯気を照らす。洗濯ロープの肌着が揺れる。前夜の取立日の名残（地面に落ちた提灯、剥がれた告知）が路地の隅に転がっている。", "dialogue": "", "dialogue_en": "", "sound": "【SE】遠くの鍋の湯が沸く音、トントンと包丁のリズム、底帳の朝の生活音（シャッター、咳払い）。【BGM】なし"}, {"no": 34, "seq": "t1", "local": 2, "scene": "底帳・麺屋台「霧島」・裏の物置・朝", "start": 199.0, "sec": 7.0, "frames": [], "camera": "FIX", "shot": "MS", "picture": "裏の物置。天井近くまで積んだ麺袋の山。その頂上でジンが大の字で寝ている（首に屋台の手ぬぐい、片袖を切った紺の作業着）。板壁の隙間から光の筋が三本。", "action": "壁越しに包丁の音が規則正しく続く。リズムに合わせてジンの鼻がピクッ、ピクッと動く。", "dialogue": "", "dialogue_en": "", "sound": "【SE】包丁のリズム（壁越し・こもり気味）、ジンの寝息"}, {"no": 35, "seq": "t1", "local": 3, "scene": "底帳・麺屋台「霧島」・裏の物置・朝", "start": 206.0, "sec": 3.0, "frames": [], "camera": "FIX", "shot": "ECU", "picture": "ジンの目。カッと見開く。瞳に一瞬だけ、長い手袋の指先が迫る残像（アバン最終カットの反復、白フラッシュ2コマ）。", "action": "残像は2コマで消え、瞳には天井の梁だけが映る。", "dialogue": "", "dialogue_en": "", "sound": "【SE】心音一拍（アバンの心音と同じ音色）。包丁の音が一瞬だけ遠のき、戻る"}, {"no": 36, "seq": "t1", "local": 4, "scene": "底帳・麺屋台「霧島」・裏の物置・朝", "start": 209.0, "sec": 11.0, "frames": [], "camera": "T.B.", "shot": "MS→FS", "picture": "跳ね起きたジン。勢いで麺袋の山が崩れ、ジンごと床へ雪崩落ちる。T.B. しきると、麺袋に埋もれて顔だけ出したジン。", "action": "最後の一袋が遅れて頭に「ぽすっ」と落ちる（ギャグの間を1拍置く）。ジン、袋の中から片手を出して喉をさする。ゴクリと唾をのみ、息を整える。", "dialogue": "", "dialogue_en": "", "sound": "【SE】ドサドサドサ（麺袋の落下）→ぽすっ。壁の向こうの包丁音は一度も途切れない"}, {"no": 37, "seq": "t1", "local": 5, "scene": "底帳・麺屋台「霧島」・裏の物置・朝", "start": 220.0, "sec": 12.0, "frames": [], "camera": "FIX→T.B.", "shot": "CU→BS", "picture": "ジンの左手首。手首から肘までの赤い印。脈打つでも這い上がるでもなく、ただ赤いだけ。T.B. してジンの顔を入れる。", "action": "ジン、手首を表、裏と返して確かめる。何も起きない。天井を見上げ、大きく息を吐いて脱力。", "dialogue": "ジン「……生きてる」", "dialogue_en": "\"...I'm alive.\"", "sound": "【SE】静寂寄り。包丁の音だけ"}, {"no": 38, "seq": "t1", "local": 6, "scene": "底帳・麺屋台「霧島」・裏の物置・朝", "start": 232.0, "sec": 9.0, "frames": [], "camera": "FIX", "shot": "MS", "picture": "物置の出入口ナメ。手前に麺袋に埋もれたジンの後ろ頭、奥の暖簾越しに逆光で包丁を振るうケイのシルエット。こちらを見ない。", "action": "ケイの台詞の間も包丁のリズムは一定。台詞の終わりに一回だけ、まな板を強く「ダン」と叩く。", "dialogue": "ケイ（OFF）「生きてるならネギ切りな。配達五件すっぽかした分」", "dialogue_en": "\"If you're alive, chop the scallions. That's for the five deliveries you skipped.\"", "sound": "【SE】包丁のリズム→ダン"}, {"no": 39, "seq": "t1", "local": 7, "scene": "底帳・麺屋台「霧島」・裏の物置・朝", "start": 241.0, "sec": 9.0, "frames": [], "camera": "PAN", "shot": "CU→BS", "picture": "物置の柱に貼られた配達伝票の束。五枚すべてに「未配達」の判（ケイの太い字で上書き）。PAN してジンの顔へ。", "action": "ジン、指を折って数え始め、五本目で手が止まる。もう片方の手も出して数え直し、首をかしげる。", "dialogue": "ジン「……五件も？」", "dialogue_en": "\"...Five?\"", "sound": "【SE】伝票が隙間風でパラパラめくれる音"}, {"no": 40, "seq": "t1", "local": 8, "scene": "底帳・麺屋台「霧島」・裏の物置・朝", "start": 250.0, "sec": 10.0, "frames": [], "camera": "FIX→FOLLOW", "shot": "FS", "picture": "物置全景。麺袋から脱出しようともがくジン。", "action": "片足を抜いた拍子に袋に足を取られ、もう一度前のめりに転ぶ。起き上がって手ぬぐいを頭に巻き直し、暖簾を突き破るように表へ駆け出す。FOLLOW で暖簾まで追い、暖簾の揺れで切る。", "dialogue": "ジン「切る切る切る！ 今切るって！」", "dialogue_en": "\"Chopping! Chopping! I'm on it!\"", "sound": "【SE】ドタッ（転倒）、暖簾のはためき"}, {"no": 41, "seq": "t1", "local": 9, "scene": "同・屋台・カウンター・朝", "start": 260.0, "sec": 5.0, "frames": [], "camera": "FIX", "shot": "MS", "picture": "屋台のカウンター越し。湯気の向こうでケイが麺を打つ（黒髪をきつくまとめ、こめかみに白髪、左頬に古い傷、割烹着）。日焼けした右腕、左の袖だけ手首まで下ろしている。カウンター端でツバメ（ゴーグル、ぶかぶかパーカー）がタダで麺をすする。手前でジンがネギを刻み始める。", "action": "三人三様のリズム：ケイの麺打ち、ツバメのすする音、ジンの包丁（ジンだけテンポがずれている）。", "dialogue": "", "dialogue_en": "", "sound": "【SE】麺を打つ音、ずずっ、包丁"}, {"no": 42, "seq": "t1", "local": 10, "scene": "同・屋台・カウンター・朝", "start": 265.0, "sec": 6.0, "frames": [], "camera": "FIX", "shot": "BS", "picture": "ツバメ、丼を抱えたまま、すきっ歯でニヤニヤ。", "action": "箸でジンを指しながらしゃべる。", "dialogue": "ツバメ「おはよ、ZEROアニキ。昨日すごかったね。路地から見てたよ、仮面のやつに睨まれて固まってんの」", "dialogue_en": "\"Morning, Big Bro Zero. Last night was wild. I saw you from the alley — frozen stiff under that mask.\"", "sound": ""}, {"no": 43, "seq": "t1", "local": 11, "scene": "同・屋台・カウンター・朝", "start": 271.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "BS", "picture": "ジン、包丁を止めずに目だけツバメへ。", "action": "ネギが乱切りになっていく。", "dialogue": "ジン「固まってねえ。様子見だ」", "dialogue_en": "\"I wasn't frozen. I was assessing.\"", "sound": "【SE】包丁（乱れたリズム）"}, {"no": 44, "seq": "t1", "local": 12, "scene": "同・屋台・カウンター・朝", "start": 275.0, "sec": 7.0, "frames": [], "camera": "FIX→Q.T.U.", "shot": "2S→CU", "picture": "ジンとツバメの2ショット。ツバメのパーカーのポケットから、ジンの手ぬぐいと同じ柄の小銭入れが半分のぞいている。Q.T.U. でポケットへ。", "action": "ジンの台詞と同時に、ツバメの指が小銭入れをそっとポケットの奥へ押し込む。", "dialogue": "ツバメ「あたしの財布から小銭抜くより震えてた」\nジン「お前が俺から抜いてんだよ」", "dialogue_en": "\"You were shakier than when you pick my wallet.\"\n\"YOU pick MINE.\"", "sound": "【SE】チャリ（小銭入れ）"}, {"no": 45, "seq": "t1", "local": 13, "scene": "同・屋台・カウンター・朝", "start": 282.0, "sec": 6.0, "frames": [], "camera": "FIX", "shot": "CU", "picture": "ジンの横顔。包丁の手が少しゆっくりになり、目が遠くなる。", "action": "ネギを刻むリズムが一定に戻る（考えごとをすると手が丁寧になる、というジンの癖）。", "dialogue": "ジン「でもさ、変なんだよ。あいつ、俺の顔じっと見て……」", "dialogue_en": "\"But it was weird. He just stared at my face...\"", "sound": ""}, {"no": 46, "seq": "t1", "local": 14, "scene": "同・屋台・カウンター・朝", "start": 288.0, "sec": 3.0, "frames": [], "camera": "FIX（回想）", "shot": "BS", "picture": "回想フラッシュ（袋小路・前夜）。ジンの喉の手前で止まった長い手袋の指。その奥にニル：象牙色の長方形の仮面（閉じた帳簿の表紙形、横一本のスリット、片側に背表紙の綴じ目）、平たいつばの制帽、高い立ち襟。", "action": "低彩度・ザラつき処理。指が止まったまま、仮面のスリットだけがわずかにジンの顔へ傾く。（L-2対応：口頭説明だけにせず短く見せる）", "dialogue": "ニル「……今夜は、お前じゃない」", "dialogue_en": "\"...Not you. Not tonight.\"", "sound": "【SE】空気の圧が変わる低いうなり（短く）"}, {"no": 47, "seq": "t1", "local": 15, "scene": "同・屋台・カウンター・朝", "start": 291.0, "sec": 6.0, "frames": [], "camera": "PAN UP", "shot": "CU→BS", "picture": "まな板の上、麺を切るケイの包丁がピタリと止まる。PAN UP してケイの顔。視線は手元のまま。", "action": "一拍おいて、ケイが短く答える。表情は動かさない。", "dialogue": "ケイ「……そう」", "dialogue_en": "\"...Is that so.\"", "sound": "【SE】包丁のリズムが途切れる。無音1拍。湯の沸く音だけ"}, {"no": 48, "seq": "t1", "local": 16, "scene": "同・屋台・カウンター・朝", "start": 297.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "BS", "picture": "ジン、刻む手を止めてケイを見る。", "action": "何気ない調子で訊く。", "dialogue": "ジン「ケイ、ニルって知ってる？」", "dialogue_en": "\"Kei, you know a guy called Nil?\"", "sound": ""}, {"no": 49, "seq": "t1", "local": 17, "scene": "同・屋台・カウンター・朝", "start": 301.0, "sec": 5.0, "frames": [], "camera": "FIX", "shot": "MS", "picture": "ケイ、何事もなかったように麺を湯に放る。", "action": "背中で答える。湯切りざるを振る手つきはいつも通り。", "dialogue": "ケイ「取立人なんてみんな同じ顔さ。仮面だからね」", "dialogue_en": "\"Collectors all have the same face. They wear masks.\"", "sound": "【SE】麺が湯に落ちる音、包丁再開"}, {"no": 50, "seq": "t1", "local": 18, "scene": "同・屋台・カウンター・朝", "start": 306.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "CU", "picture": "ツバメ。麺をすすりながら、横目でケイの横顔をちらりと見る。", "action": "箸が一瞬止まり、何も言わずにまたすする。", "dialogue": "", "dialogue_en": "", "sound": "【SE】ずずっ……（止まる）……ずずっ"}, {"no": 51, "seq": "t1", "local": 19, "scene": "底帳／中層の境界「関所ゲート」・昼", "start": 310.0, "sec": 5.0, "frames": [], "camera": "PAN UP", "shot": "LS あおり", "picture": "肋骨の内側を登る巨大な階段。岡持ちを下げたジンと、後ろをついてくるツバメ。PAN UP すると階段の上に関所ゲート（骨に打ち込まれた鉄の門と照会機のアーチ）。", "action": "ジンは岡持ちを水平に保ったまま二段飛ばし。ツバメは手すりを滑って追いつく。", "dialogue": "", "dialogue_en": "", "sound": "【BGM】日常曲（軽いギターとパーカッション）、イン。【SE】階段の足音、上層からの雑踏"}, {"no": 52, "seq": "t1", "local": 20, "scene": "底帳／中層の境界「関所ゲート」・昼", "start": 315.0, "sec": 8.0, "frames": [], "camera": "PAN", "shot": "LS→MS", "picture": "ゲート前の長い列。人々が順に手首を照会機のアーチにかざす。手首の印がそれぞれの貸主の色に光る。PAN して身なりのいい男の番へ。", "action": "Cの客は普通に通過。Bの男の足元には優先レーンの床ランプが点き、男だけ動く歩道で運ばれていく（格差のギャグ）。", "dialogue": "照会機「格付けC。通行可」\n照会機「格付けB。通行可。優先レーンへどうぞ」", "dialogue_en": "\"Rating C. Cleared.\"\n\"Rating B. Cleared. Please proceed to the priority lane.\"", "sound": "【SE】ピッ（C）、上品なチャイム（B）"}, {"no": 53, "seq": "t1", "local": 21, "scene": "底帳／中層の境界「関所ゲート」・昼", "start": 323.0, "sec": 7.0, "frames": [], "camera": "FIX→T.U.", "shot": "CU→ECU", "picture": "ジンの番。赤い印の左手首をアーチにかざす。T.U. して照会機の画面。他の客より明らかに大きな書体で「ZERO」。", "action": "ジンは口笛まじりに気楽にかざす。画面の文字が一瞬ノイズで揺れてから「ZERO」に落ち着く。", "dialogue": "照会機「格付け：ZERO。与信なし。通行不可」", "dialogue_en": "\"Rating: ZERO. No credit. Entry denied.\"", "sound": "【SE】口笛→ブザー（長め）"}, {"no": 54, "seq": "t1", "local": 22, "scene": "底帳／中層の境界「関所ゲート」・昼", "start": 330.0, "sec": 3.0, "frames": [], "camera": "FIX", "shot": "MS", "picture": "ブザーと同時に警告灯が回り、遮断バーがジンの岡持ちの寸前にガシャンと落ちる。", "action": "岡持ちのフタだけが跳ね上がり、中の丼は無事。ジン、フタを片手でキャッチ。", "dialogue": "", "dialogue_en": "", "sound": "【SE】ガシャン、警告灯の回転音"}, {"no": 55, "seq": "t1", "local": 23, "scene": "底帳／中層の境界「関所ゲート」・昼", "start": 333.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "LS 俯瞰", "picture": "真上からの俯瞰。行列の中、ジンの周囲だけ人の輪がずざっと後退し、ぽっかりと円形の空間が空く。", "action": "輪の縁で人々が手首を袖で隠す。", "dialogue": "", "dialogue_en": "", "sound": "【SE】ざわめき、後ずさる足音"}, {"no": 56, "seq": "t1", "local": 24, "scene": "底帳／中層の境界「関所ゲート」・昼", "start": 337.0, "sec": 6.0, "frames": [], "camera": "FIX→Q.T.U.", "shot": "MS→CU", "picture": "輪の縁の母子。母親が子ども（5歳くらい）の手を引いて離れる。Q.T.U. で振り返る子どもの顔。", "action": "子どもは引っ張られながらも、ジンの赤い腕から目を離さない。", "dialogue": "母親「見ちゃだめ。ゼロがうつる」", "dialogue_en": "\"Don't look. Zero is catching.\"", "sound": ""}, {"no": 57, "seq": "t1", "local": 25, "scene": "底帳／中層の境界「関所ゲート」・昼", "start": 343.0, "sec": 6.0, "frames": [], "camera": "FIX", "shot": "BS→MS", "picture": "ジン、子どもに手を振って、ニッと笑う。", "action": "子どもがつられて手を振り返しかけたところで、母親に腕ごと引っ張られて画面外へスッと消える。ジンの手だけが空中に残る（間）。", "dialogue": "ジン「うつんねえよ。うつったら俺がびっくりするわ」", "dialogue_en": "\"It's not catching. If it were, I'd be the one surprised.\"", "sound": ""}, {"no": 58, "seq": "t1", "local": 26, "scene": "底帳／中層の境界「関所ゲート」・昼", "start": 349.0, "sec": 7.0, "frames": [], "camera": "FIX", "shot": "MS", "picture": "ゲートの衛兵が警棒で岡持ちを小突く。", "action": "ジン、岡持ちを守るように半回転してから、敬礼のまねをして裏階段の方へ。", "dialogue": "衛兵「ZEROは配達も裏口だ。下へ回れ」\nジン「はいはい。裏口、慣れてまーす」", "dialogue_en": "\"Zeros deliver through the back. Go around below.\"\n\"Sure, sure. Back doors are my specialty.\"", "sound": "【SE】警棒が岡持ちに当たるコツン"}, {"no": 59, "seq": "t1", "local": 27, "scene": "底帳／中層の境界「関所ゲート」・昼", "start": 356.0, "sec": 6.0, "frames": [], "camera": "PAN UP", "shot": "LS あおり", "picture": "ジンの背後、ゲートの上に巨大な〈公開格付け〉。最下段の暗い列に「ZERO／名前表示なし」。PAN UP しきると最上段に「AA　榊ドウゲン　18歳　無延滞記録更新中」が輝く。", "action": "最上段の文字だけ光が流れている。※ドウゲンは名前のみ、本人は描かない（初登場は第3話）。", "dialogue": "", "dialogue_en": "", "sound": "【SE】掲示板の電子音、文字が流れる音"}, {"no": 60, "seq": "t1", "local": 28, "scene": "底帳／中層の境界「関所ゲート」・昼", "start": 362.0, "sec": 11.0, "frames": [], "camera": "FIX", "shot": "2S", "picture": "裏階段の踊り場、掲示板を見上げるツバメと、岡持ちを持ち直すジン。", "action": "ツバメは両手を頬に当ててうっとり。ジンは見上げもせずに言い返す。最後にツバメが半目でジンを見る。", "dialogue": "ツバメ「いいなー、AA。あの人、一回も延滞したことないんだって」\nジン「借りたもん全部返せる奴なんて、そもそも借りなくていい奴だろ」\nツバメ「ひねくれてる〜」", "dialogue_en": "\"Must be nice, being AA. Word is he's never missed a single payment.\"\n\"Anyone who can pay back everything never needed to borrow in the first place.\"\n\"So jaded~\"", "sound": ""}, {"no": 61, "seq": "t1", "local": 29, "scene": "底帳／中層の境界「関所ゲート」・昼", "start": 373.0, "sec": 8.0, "frames": [], "camera": "FOLLOW", "shot": "MS", "picture": "裏階段を下りながら、ツバメが得意げに指を立てる。", "action": "ツバメの説明に合わせて、画面の端に彼女の落書き風イメージがポップアップ（決済円で殴り合う棒人間→王冠→下手な神さまの絵に「なんでも1コ」の吹き出し）。", "dialogue": "ツバメ「でもさ、知ってる？ 公認の決済戦〈セトルメント〉で勝てば、負けた奴の与信枠を奪える。〈大決算〉で優勝したら、貸主の神さまに何でも一つお願いできるんだって。借金の帳消しでも」", "dialogue_en": "\"But did you know? Win an official Settlement and you take the loser's credit line. Win the Grand Settlement and the lender gods grant you one wish. Even wiping out a debt.\"", "sound": "【SE】落書きのポップ音（ポン、ポン、ポン）"}, {"no": 62, "seq": "t1", "local": 30, "scene": "底帳／中層の境界「関所ゲート」・昼", "start": 381.0, "sec": 3.0, "frames": [], "camera": "FIX", "shot": "BS", "picture": "ジン、前を向いたまま。", "action": "口だけ動かす。", "dialogue": "ジン「知ってるよ。百回聞いた」", "dialogue_en": "\"I know. You've told me a hundred times.\"", "sound": ""}, {"no": 63, "seq": "t1", "local": 31, "scene": "底帳／中層の境界「関所ゲート」・昼", "start": 384.0, "sec": 8.0, "frames": [], "camera": "FIX", "shot": "MS→BS", "picture": "ツバメ、自分の手首の翠の印（格付けD）を見せびらかす。", "action": "言いかけたところで、ジンの台詞がかぶる。", "dialogue": "ツバメ「でもエントリーは格付けD以上。ZEROが出るには、担保を出す保証人がいる。アニキにそんな知り合い——」\nジン「出らんねえ。それも百回聞いた」", "dialogue_en": "\"But you need a D rating to enter. A Zero needs a guarantor to put up collateral. Like you'd know anyone who—\"\n\"I can't enter. Heard that a hundred times too.\"", "sound": "【SE】印の「チン」（ツバメが軽く光らせる）"}, {"no": 64, "seq": "t1", "local": 32, "scene": "底帳／中層の境界「関所ゲート」・昼", "start": 392.0, "sec": 8.0, "frames": [], "camera": "FIX→T.U.", "shot": "MS→CU", "picture": "ジン、笑って岡持ちでツバメの頭を軽くポコッ。T.U. してジンの横顔。", "action": "笑ったままの口元。だが目だけが、遠ざかる掲示板の最上段から離れない。", "dialogue": "", "dialogue_en": "", "sound": "【SE】ポコッ、ツバメ「いてっ」（ガヤ）。【BGM】フェードアウト"}, {"no": 65, "seq": "t1", "local": 33, "scene": "カネグラ・肋骨の頂点付近・夕方", "start": 400.0, "sec": 7.0, "frames": [], "camera": "T.B.", "shot": "ELS", "picture": "底帳を一望できる骨の上。眼下に夕陽に照らされた違法建築の海。T.B. しきると、遠く雲の上に白く光る塔〈バース〉。骨の稜線に小さく座る二人のシルエット。", "action": "風に乗って洗濯物と凧が流れる。", "dialogue": "", "dialogue_en": "", "sound": "【BGM】静かなピアノ、イン。【SE】高所の風"}, {"no": 66, "seq": "t1", "local": 34, "scene": "カネグラ・肋骨の頂点付近・夕方", "start": 407.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "FS", "picture": "真横から。骨の縁に並んで座り、脚をぶらぶらさせるジンとツバメ。", "action": "ツバメのサンダルが片方脱げかけ、慌てて足の指でつかみ直す（小ギャグ）。", "dialogue": "", "dialogue_en": "", "sound": "【SE】サンダルのペタ音"}, {"no": 67, "seq": "t1", "local": 35, "scene": "カネグラ・肋骨の頂点付近・夕方", "start": 411.0, "sec": 7.0, "frames": [], "camera": "FIX", "shot": "2S", "picture": "背中越しの2ショット。夕陽に向かう二人。", "action": "ツバメが顔だけジンへ向ける。ジンは即答。", "dialogue": "ツバメ「アニキさ、夢とかある？」\nジン「ある」\nツバメ「金持ちになる？」\nジン「ちげえよ」", "dialogue_en": "\"Bro, you got a dream?\"\n\"Yeah.\"\n\"Getting rich?\"\n\"Nope.\"", "sound": ""}, {"no": 68, "seq": "t1", "local": 36, "scene": "カネグラ・肋骨の頂点付近・夕方", "start": 418.0, "sec": 5.0, "frames": [], "camera": "T.U.", "shot": "CU", "picture": "ジン、赤い左腕を夕陽にかざす。腕の赤と夕陽が重なり、輪郭が光る。", "action": "指を開くと、指の間から夕陽がこぼれる。", "dialogue": "", "dialogue_en": "", "sound": "【BGM】ピアノの和音が一段上がる"}, {"no": 69, "seq": "t1", "local": 37, "scene": "カネグラ・肋骨の頂点付近・夕方", "start": 423.0, "sec": 5.0, "frames": [], "camera": "FIX", "shot": "BS 逆光", "picture": "ジンの横顔、逆光のシルエット。", "action": "腕を下ろしながら、静かに言う。", "dialogue": "ジン「父ちゃんの借金をゼロにする。それから——」", "dialogue_en": "\"I'm gonna zero out my old man's debt. And then—\"", "sound": ""}, {"no": 70, "seq": "t1", "local": 38, "scene": "カネグラ・肋骨の頂点付近・夕方", "start": 428.0, "sec": 6.0, "frames": [], "camera": "T.U.", "shot": "MS（肩ナメ）→LS", "picture": "ジンの肩ナメ。ジンが遠くの〈バース〉を指差す。指先の先へ T.U. して、雲の上の白い塔。", "action": "塔の頂で取引所の灯がひとつ点る。", "dialogue": "ジン「この街の帳簿を、全部燃やす」", "dialogue_en": "\"I'm gonna burn this city's ledger to the ground.\"", "sound": "【BGM】ピアノの主旋律（ここがメインテーマの初出）"}, {"no": 71, "seq": "t1", "local": 39, "scene": "カネグラ・肋骨の頂点付近・夕方", "start": 434.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "2S（背中）", "picture": "二人の背中、塔を見ている。", "action": "ツバメが小さく口を開け、ジンが得意げに鼻を鳴らす。", "dialogue": "ツバメ「……でっか」\nジン「だろ」", "dialogue_en": "\"...That's huge.\"\n\"Right?\"", "sound": ""}, {"no": 72, "seq": "t1", "local": 40, "scene": "カネグラ・肋骨の頂点付近・夕方", "start": 438.0, "sec": 11.0, "frames": [], "camera": "FIX（切り返し）", "shot": "BS→BS", "picture": "ツバメのBS→ジンのBSへ切り返し（1カット内で手持ちに近いゆるい振り）。", "action": "ジン、笑いを残したまま答え、言い終わると目を閉じる。", "dialogue": "ツバメ「アニキの父ちゃんって、どんな人だったの？」\nジン「知らねえ。俺が四つのときにいなくなった。写真も一枚もねえ」", "dialogue_en": "\"What was your dad like?\"\n\"No idea. He vanished when I was four. Not a single photo.\"", "sound": "【BGM】ピアノ、音数が減る"}, {"no": 73, "seq": "t1", "local": 41, "scene": "カネグラ・肋骨の頂点付近・夕方", "start": 449.0, "sec": 10.0, "frames": [], "camera": "手持ち・微揺れ→T.U.", "shot": "MS→CU", "picture": "回想。ザラついたフィルム質感、赤い提灯の光。しゃがみ込んで幼いジン（4歳）と目線を合わせる男。T.U. して男の顔をはっきり見せる：左の眉に古い切り傷、笑うと片目だけ細くなる。", "action": "※この顔のレイアウト・角度を設定として固定（S3の代償カット「父の顔が白く抜ける」で同一構図を使う）。男がゆっくり笑い、片目だけ細くなる。", "dialogue": "", "dialogue_en": "", "sound": "【SE】遠い夜市の雑踏（回想用にこもらせる）、提灯の揺れる音"}, {"no": 74, "seq": "t1", "local": 42, "scene": "カネグラ・肋骨の頂点付近・夕方", "start": 459.0, "sec": 5.0, "frames": [], "camera": "FIX", "shot": "CU", "picture": "大きな手が、幼いジンの頭に置かれる。", "action": "男が何か言いかけたところで、画面がフィルムの焼けのように端から白く飛び、ブツッと途切れる。", "dialogue": "父（回想）「ジン。借りたもんはな……」", "dialogue_en": "\"Jin. Whatever you borrow...\"", "sound": "【SE】フィルムが切れるノイズ→ブツッ（無音1拍）"}, {"no": 75, "seq": "t1", "local": 43, "scene": "カネグラ・肋骨の頂点付近・夕方", "start": 464.0, "sec": 6.0, "frames": [], "camera": "FIX", "shot": "BS", "picture": "現在。ジン、目を開ける。夕陽が少し沈んでいる。", "action": "自分の眉を指でなぞりながら話す。", "dialogue": "ジン「覚えてんのは、顔だけ。眉んとこに傷があって、笑うと片目だけ細くなんの。それで、何か言いかけてた」", "dialogue_en": "\"All I remember is his face. A scar on his eyebrow, and one eye squints when he smiles. And he was about to tell me something.\"", "sound": "【BGM】ピアノ再開"}, {"no": 76, "seq": "t1", "local": 44, "scene": "カネグラ・肋骨の頂点付近・夕方", "start": 470.0, "sec": 7.0, "frames": [], "camera": "FIX→T.U.", "shot": "2S→BS", "picture": "ツバメが首をかしげる。T.U. してジン。", "action": "ジン、肩をすくめて笑う。最後の台詞は自信満々に（後の代償の皮肉として、言い切りを強調）。", "dialogue": "ツバメ「何て？」\nジン「さあ。続き、忘れた。顔だけは絶対忘れねえけどな」", "dialogue_en": "\"Say what?\"\n\"Dunno. Forgot the rest. But his face — I'll never forget that.\"", "sound": ""}, {"no": 77, "seq": "t1", "local": 45, "scene": "カネグラ・肋骨の頂点付近・夕方", "start": 477.0, "sec": 3.0, "frames": [], "camera": "FIX", "shot": "CU", "picture": "ジンの左手首。膝の上に置かれた赤い印。", "action": "印がかすかに一度だけ脈打つ。ジンは気づかない（プラント：父の顔）。", "dialogue": "", "dialogue_en": "", "sound": "【SE】ごく小さな心音一拍。ピアノの一音が半音ずれて残る"}, {"no": 78, "seq": "t1", "local": 46, "scene": "麺屋台「霧島」・夜（店じまい）", "start": 480.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "LS", "picture": "店じまいの麺屋台「霧島」。提灯が半分消えている。カウンターでケイが売上の小銭を数えている。", "action": "遠くで犬が鳴く。", "dialogue": "", "dialogue_en": "", "sound": "【SE】小銭の音、虫の声。【BGM】なし"}, {"no": 79, "seq": "t1", "local": 47, "scene": "麺屋台「霧島」・夜（店じまい）", "start": 484.0, "sec": 6.0, "frames": [], "camera": "FIX→T.B.", "shot": "CU→BS", "picture": "ケイの手元。小銭を十枚ずつ積む。最後の山が足りない。T.B. してケイ。", "action": "崩してもう一度数え直す。やはり足りない。小さくため息をつき、額をこする。", "dialogue": "", "dialogue_en": "", "sound": "【SE】小銭を崩す音、ため息"}, {"no": 80, "seq": "t1", "local": 48, "scene": "麺屋台「霧島」・夜（店じまい）", "start": 490.0, "sec": 6.0, "frames": [], "camera": "FIX", "shot": "MS", "picture": "暖簾をくぐってジンが入ってくる。腕の擦り傷を見せながら。", "action": "ケイは顔も上げず小銭を袋に戻す。", "dialogue": "ジン「ケイ、絆創膏ある？」\nケイ「唾つけときな」", "dialogue_en": "\"Kei, got a band-aid?\"\n\"Spit on it.\"", "sound": "【SE】暖簾の音"}, {"no": 81, "seq": "t1", "local": 49, "scene": "麺屋台「霧島」・夜（店じまい）", "start": 496.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "MS", "picture": "文句を言いつつ、ケイが救急箱を出し、ジンの腕に包帯を巻く。", "action": "ジンが大げさに痛がるふり→ケイが包帯をきゅっと締めて本当に痛がらせる（小ギャグ）。", "dialogue": "ジン「いでっ」", "dialogue_en": "\"Ow!\"", "sound": "【SE】包帯の擦れ、きゅっ"}, {"no": 82, "seq": "t1", "local": 50, "scene": "麺屋台「霧島」・夜（店じまい）", "start": 500.0, "sec": 7.0, "frames": [], "camera": "T.U.", "shot": "CU→ECU", "picture": "包帯を巻くケイの腕の動きで、左袖がめくれる。T.U. して前腕の古い焼印：帳簿の罫線の上に×印を重ねた紋章（取立人の“退職印”）。", "action": "焼印は肌に沈んだ古い傷の質感。罫線の本数は後の第7話の設定画と一致させる（プラント：ケイのコレクター傷）。", "dialogue": "", "dialogue_en": "", "sound": "【SE】低い単音（劇伴ではなくMAの持続音）"}, {"no": 83, "seq": "t1", "local": 51, "scene": "麺屋台「霧島」・夜（店じまい）", "start": 507.0, "sec": 5.0, "frames": [], "camera": "FIX", "shot": "ECU→BS", "picture": "ジンの目がそこで止まる。→BS。", "action": "痛がっていた顔のまま固まり、声だけ低くなる。", "dialogue": "ジン「……それ、なに」", "dialogue_en": "\"...What's that?\"", "sound": ""}, {"no": 84, "seq": "t1", "local": 52, "scene": "麺屋台「霧島」・夜（店じまい）", "start": 512.0, "sec": 7.0, "frames": [], "camera": "FIX", "shot": "BS→2S", "picture": "ケイ、何気ない手つきで袖を下ろす。2Sへ。", "action": "ケイはジンと目を合わせずに包帯の端を整える。", "dialogue": "ケイ「昔の火傷。鍋ひっくり返したの」\nジン「ケイが鍋ひっくり返すとこ、見たことねえけど」\nケイ「だから昔なんだよ」", "dialogue_en": "\"Old burn. Knocked over a pot.\"\n\"I've never seen you knock over a pot.\"\n\"That's why I said 'old.'\"", "sound": ""}, {"no": 85, "seq": "t1", "local": 53, "scene": "麺屋台「霧島」・夜（店じまい）", "start": 519.0, "sec": 3.0, "frames": [], "camera": "FIX", "shot": "CU", "picture": "ケイ、包帯を結び、ジンの額を指で弾く。", "action": "ジンがのけぞる。", "dialogue": "", "dialogue_en": "", "sound": "【SE】ペシッ"}, {"no": 86, "seq": "t1", "local": 54, "scene": "麺屋台「霧島」・夜（店じまい）", "start": 522.0, "sec": 6.0, "frames": [], "camera": "FIX", "shot": "BS", "picture": "ケイの正面。初めて真っすぐジンを見る。", "action": "声は大きくしない。（ケイは大声を出さない）", "dialogue": "ケイ「ジン。もしあの仮面がまた来たら、逃げな。何があっても、振り返らずに」", "dialogue_en": "\"Jin. If that mask comes back, run. No matter what happens. Don't look back.\"", "sound": "【SE】湯の沸く音が止む（ガスを切る）"}, {"no": 87, "seq": "t1", "local": 55, "scene": "麺屋台「霧島」・夜（店じまい）", "start": 528.0, "sec": 5.0, "frames": [], "camera": "FIX", "shot": "BS 切り返し", "picture": "ジン→ケイ。", "action": "ケイは一拍置いて、いつもの皮肉顔に戻る。", "dialogue": "ジン「……なんでだよ」\nケイ「店の看板息子が死んだら、客が減る」", "dialogue_en": "\"...Why?\"\n\"If the shop's poster boy dies, we lose customers.\"", "sound": ""}, {"no": 88, "seq": "t1", "local": 56, "scene": "麺屋台「霧島」・夜（店じまい）", "start": 533.0, "sec": 4.0, "frames": [], "camera": "FIX→Q.T.U.", "shot": "2S→CU", "picture": "ジンが笑う。ケイも笑う。Q.T.U. してケイの目。", "action": "口元は笑っているが、ケイの目は笑っていない。", "dialogue": "", "dialogue_en": "", "sound": "【SE】二人の短い笑い声"}, {"no": 89, "seq": "t1", "local": 57, "scene": "麺屋台「霧島」・夜（店じまい）", "start": 537.0, "sec": 3.0, "frames": [], "camera": "FIX", "shot": "CU", "picture": "ケイの左手首。色あせた藍の印に「期日超過：3」の文字。", "action": "ケイは手のひらでそれを隠す。", "dialogue": "", "dialogue_en": "", "sound": "【SE】印の点滅音（弱く、濁った「チ…」）"}, {"no": 90, "seq": "t1", "local": 58, "scene": "麺屋台「霧島」・夜（店じまい）", "start": 540.0, "sec": 6.0, "frames": [], "camera": "FIX", "shot": "LS", "picture": "屋台の背後越し、向かいの屋根。月を背に、仮面の取立人のシルエット：平たいつばの制帽、高い立ち襟のフロックコート、長方形の仮面に横一本のスリットが月光を反射する。フードはなし。", "action": "動かない。こちらを見下ろしている。手前のジンとケイは気づかない。", "dialogue": "", "dialogue_en": "", "sound": "【SE】低いうなり（ごく微か）"}, {"no": 91, "seq": "t1", "local": 59, "scene": "麺屋台「霧島」・夜（店じまい）", "start": 546.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "ECU", "picture": "【SKIP-PROOF／アイキャッチ代わり】ジンの手首の赤い印が画面いっぱいに脈打つ。", "action": "二度脈打ち、二度目で画面全体がわずかに赤く滲む。", "dialogue": "？？？（子どもの声）「ねえ」", "dialogue_en": "\"Hey.\"", "sound": "【SE】心音×2"}, {"no": 92, "seq": "t1", "local": 60, "scene": "麺屋台「霧島」・夜（ニル来店）", "start": 550.0, "sec": 5.0, "frames": [], "camera": "FIX", "shot": "LS", "picture": "屋台の外観。軒先の提灯が並ぶ。", "action": "風もないのに、提灯が手前から奥へ一つずつ消えていく。最後の一つだけが残る。", "dialogue": "", "dialogue_en": "", "sound": "【SE】フッ、フッ、フッ、フッ（火が消える音）。虫の声がぴたりと止む。【BGM】なし"}, {"no": 93, "seq": "t1", "local": 61, "scene": "麺屋台「霧島」・夜（ニル来店）", "start": 555.0, "sec": 3.0, "frames": [], "camera": "FIX", "shot": "MS", "picture": "屋台の中。仕込みをしていたケイが手を止め、顔を上げる。奥でジンが丼を洗っている（背景、ピン送りでボケ）。", "action": "ケイの包丁を握る手に力が入る。", "dialogue": "", "dialogue_en": "", "sound": "【SE】洗い物の水音（奥）"}, {"no": 94, "seq": "t1", "local": 62, "scene": "麺屋台「霧島」・夜（ニル来店）", "start": 558.0, "sec": 5.0, "frames": [], "camera": "FIX", "shot": "FS あおり（暖簾ナメ）", "picture": "暖簾をくぐってニルが入ってくる。平たいつばの制帽が暖簾を押し分け、低い軒に合わせて上体をきっちり直角に折る。灰色の刈り込んだ髪、高い立ち襟の黒いフロックコート、象牙色の帳簿表紙形の仮面（横一本のスリット、背表紙の綴じ目）、異様に長い手袋の指。", "action": "足音がない。暖簾の布ずれだけが鳴る。", "dialogue": "", "dialogue_en": "", "sound": "【SE】暖簾の布ずれのみ"}, {"no": 95, "seq": "t1", "local": 63, "scene": "麺屋台「霧島」・夜（ニル来店）", "start": 563.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "MS", "picture": "ニル、カウンターに座る。丸椅子が細長い体に対して小さすぎ、膝が高く突き出る（静かな違和感のギャグ）。", "action": "長い指を揃えてカウンターに置く。", "dialogue": "ニル「一杯」", "dialogue_en": "\"One bowl.\"", "sound": "【SE】丸椅子のきしみ"}, {"no": 96, "seq": "t1", "local": 64, "scene": "麺屋台「霧島」・夜（ニル来店）", "start": 567.0, "sec": 7.0, "frames": [], "camera": "FIX", "shot": "BS 切り返し", "picture": "ケイ→ニル。", "action": "ケイは包丁を置かない。ニルは仮面を動かさない。", "dialogue": "ケイ「……閉店だよ」\nニル「なら、用件だけ」", "dialogue_en": "\"...We're closed.\"\n\"Then, business only.\"", "sound": ""}, {"no": 97, "seq": "t1", "local": 65, "scene": "麺屋台「霧島」・夜（ニル来店）", "start": 574.0, "sec": 10.0, "frames": [], "camera": "FIX→T.B.", "shot": "CU→BS", "picture": "ニルが小さな黒い帳簿を開く。頁が勝手にめくれ、光の文字が浮かぶ。T.B. してニル（帳簿の光が仮面を下から照らす）。", "action": "読み上げに合わせて光の文字が一行ずつ浮く：「霧島ケイ」「旧・第四取立局」「延滞：3ヶ月」「特別取立状」。", "dialogue": "ニル「霧島ケイ。旧・第四取立局所属。退職時違約金、延滞三ヶ月。特別取立状により、本夜、担保の査定を行う」", "dialogue_en": "\"Kirishima Kei. Formerly of the Fourth Collection Bureau. Severance penalty, three months overdue. By special collection warrant, your collateral will be assessed tonight.\"", "sound": "【SE】頁が高速でめくれる音、光の文字が浮かぶ微かな電子音"}, {"no": 98, "seq": "t1", "local": 66, "scene": "麺屋台「霧島」・夜（ニル来店）", "start": 584.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "MS", "picture": "奥から濡れた手のままジンが出てくる。", "action": "丼を一つ持ったまま。", "dialogue": "ジン「おい、何の話だよ」", "dialogue_en": "\"Hey. What are you talking about?\"", "sound": ""}, {"no": 99, "seq": "t1", "local": 67, "scene": "麺屋台「霧島」・夜（ニル来店）", "start": 588.0, "sec": 9.0, "frames": [], "camera": "FIX→T.U.", "shot": "CU→BS", "picture": "帳簿の頁。「担保候補：〈右腕〉」の文字に一本線が走り、書き換わって「担保：〈記憶〉」。T.U. してニルの仮面。", "action": "ニルの台詞「査定変更」で文字が書き換わる。仮面のスリットがゆっくりジンへ向く。", "dialogue": "ニル「担保候補：〈右腕〉。——査定変更。担保：〈記憶〉。対象——赤羽ジンに関する一切」", "dialogue_en": "\"Proposed collateral: right arm. —Revising assessment. Collateral: memory. Subject — everything concerning Akaba Jin.\"", "sound": "【SE】文字が書き換わる擦過音→低い不協和音"}, {"no": 100, "seq": "t1", "local": 68, "scene": "麺屋台「霧島」・夜（ニル来店）", "start": 597.0, "sec": 2.0, "frames": [], "camera": "FIX", "shot": "BS", "picture": "ジン。", "action": "意味が飲み込めない顔。", "dialogue": "ジン「……は？」", "dialogue_en": "\"...Huh?\"", "sound": ""}, {"no": 101, "seq": "t1", "local": 69, "scene": "麺屋台「霧島」・夜（ニル来店）", "start": 599.0, "sec": 6.0, "frames": [], "camera": "PAN UP", "shot": "CU→BS", "picture": "ケイの手が包丁を置き、静かに手ぬぐいで手を拭く。PAN UP してケイ。", "action": "迷いのない手つき。", "dialogue": "ケイ「持っていきな」", "dialogue_en": "\"Take it.\"", "sound": "【SE】包丁をまな板に置く音"}, {"no": 102, "seq": "t1", "local": 70, "scene": "麺屋台「霧島」・夜（ニル来店）", "start": 605.0, "sec": 7.0, "frames": [], "camera": "FIX（切り返し）", "shot": "BS→BS", "picture": "ジン→ケイ（ジンを見ずに）。", "action": "ジンが身を乗り出し、ケイは目を伏せたまま言う。", "dialogue": "ジン「ケイ！？」\nケイ「ジン。逃げなって言ったろ」", "dialogue_en": "\"Kei?!\"\n\"Jin. I told you to run.\"", "sound": ""}, {"no": 103, "seq": "t1", "local": 71, "scene": "麺屋台「霧島」・夜（ニル来店）", "start": 612.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "MS", "picture": "ニル。", "action": "帳簿を片手で持ったまま、空いた手をケイへ差し伸べる。", "dialogue": "ニル「賢明だ。抵抗すれば担保が増える」", "dialogue_en": "\"Wise. Resist, and the collateral grows.\"", "sound": ""}, {"no": 104, "seq": "t1", "local": 72, "scene": "麺屋台「霧島」・夜（ニル来店）", "start": 616.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "CU", "picture": "ケイが左手首を差し出す（色あせた藍の印）。ニルの指先から光の糸が伸び、印に絡む。", "action": "糸がピンと張る。", "dialogue": "", "dialogue_en": "", "sound": "【SE】糸が張る高音"}, {"no": 105, "seq": "t1", "local": 73, "scene": "麺屋台「霧島」・夜（ニル来店）", "start": 620.0, "sec": 12.0, "frames": [], "camera": "T.U.→PAN", "shot": "MS あおり→insert×2", "picture": "ケイの頭上に、ジンとの思い出が光の頁となって浮かび上がる。①小さなジンを抱き上げる手 → PAN ②初めて麺を打つ小さなジン（粉まみれで得意顔） → PAN ③熱を出したジンの額の濡れタオル。", "action": "頁は一枚ずつめくれるように現れ、光の糸に引かれてニルの帳簿の方へ少しずつ傾いていく。", "dialogue": "", "dialogue_en": "", "sound": "【SE】紙がめくれる音×3。【BGM】オルゴール風の短いフレーズ（ケイとジンの思い出テーマ）"}, {"no": 106, "seq": "t1", "local": 74, "scene": "麺屋台「霧島」・夜（ニル来店）", "start": 632.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "CU→BS", "picture": "ジンの拳が震え、手に持っていた丼を握り直す。→BS。", "action": "", "dialogue": "ジン「やめろ！！」", "dialogue_en": "\"Stop it!!\"", "sound": "【BGM】オルゴールがブツッと切れる"}, {"no": 107, "seq": "t1", "local": 75, "scene": "麺屋台「霧島」・夜（ニル来店）", "start": 636.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "MS", "picture": "ジンがカウンター越しに丼をニルの仮面に叩きつける。", "action": "丼が粉々に砕け散る。仮面は無傷。", "dialogue": "", "dialogue_en": "", "sound": "【SE】陶器が派手に割れる音（アバン冒頭の破砕音と同じ素材）"}, {"no": 108, "seq": "t1", "local": 76, "scene": "同・屋台前の路地・夜", "start": 640.0, "sec": 7.0, "frames": [], "camera": "FIX→T.U.", "shot": "CU→ECU", "picture": "ニルの仮面。丼の破片と麺がスローで仮面から滑り落ちる。T.U. してニルの左手首の黒い印。", "action": "麺が一本だけ帽子のつばに引っかかって垂れる（1拍のギャグ）。直後、黒い印が光る。", "dialogue": "", "dialogue_en": "", "sound": "【SE】破片が落ちる音のあと無音→印の「チン」。【BGM】バトル曲（ピアノとドラムの不穏なループ）、イン"}, {"no": 109, "seq": "t1", "local": 77, "scene": "同・屋台前の路地・夜", "start": 647.0, "sec": 7.0, "frames": [], "camera": "FIX→T.B.", "shot": "BS→MS", "picture": "ニル、帽子の麺を長い指でつまんで捨てる。T.B. すると、袖口から帳簿の頁を連ねたような灰色の鎖が何本も噴き出す。", "action": "鎖の一枚一枚に罫線と数字が見える。", "dialogue": "ニル「借力、行使。〈鉄の貸主〉より——差押鎖」", "dialogue_en": "\"Borrowed power, exercised. From the Iron Lender — Seizure Chains.\"", "sound": "【SE】金属と紙が擦れ合う音、鎖が伸びる連続音"}, {"no": 110, "seq": "t1", "local": 78, "scene": "同・屋台前の路地・夜", "start": 654.0, "sec": 6.0, "frames": [], "camera": "FIX→FOLLOW", "shot": "LS→FS", "picture": "鎖の一撃で屋台の柱がへし折れ、屋根が傾く。ジンが路地へ吹き飛ばされる。FOLLOW。", "action": "ジンは石畳を転がって受け身を取る（ケイ仕込みの逃げ方：二回転して膝立ち）。", "dialogue": "", "dialogue_en": "", "sound": "【SE】木の柱が折れる音、屋根のトタンが崩れる音、転がる音"}, {"no": 111, "seq": "t1", "local": 79, "scene": "同・屋台前の路地・夜", "start": 660.0, "sec": 6.0, "frames": [], "camera": "FIX", "shot": "CU→MS", "picture": "ジンの手が、転がってきた湯切りざるを掴む。→MS、ざるを盾のように構える。", "action": "突っ込んできた鎖が、ざるの網目を素通りしてジンの鼻先でピタリと止まる（ギャグ）。", "dialogue": "ジン「……だよな」", "dialogue_en": "\"...Yeah, figured.\"", "sound": "【SE】鎖が網を抜けるシャラッ"}, {"no": 112, "seq": "t1", "local": 80, "scene": "同・屋台前の路地・夜", "start": 666.0, "sec": 7.0, "frames": [], "camera": "FOLLOW", "shot": "FS→MS", "picture": "ジン、身をひねって鎖をかわし、地面のお玉を拾う。ざる＋お玉の二刀流。", "action": "お玉で鎖を叩き落としながら前進。カン、カン、と軽い音。三本目でお玉の柄がグニャリと曲がる。", "dialogue": "", "dialogue_en": "", "sound": "【SE】カン、カン、グニャ"}, {"no": 113, "seq": "t1", "local": 81, "scene": "同・屋台前の路地・夜", "start": 673.0, "sec": 7.0, "frames": [], "camera": "FIX", "shot": "CU→MS", "picture": "崩れた屋台の脇、まだ湯気を立てる寸胴。ジンの目線が止まる。→MS。", "action": "ジン、首の手ぬぐいを手に巻いて寸胴の取っ手を掴み、振りかぶる。", "dialogue": "ジン「熱湯サービスだ、オラァ！」", "dialogue_en": "\"Hot soup — on the house!\"", "sound": "【SE】寸胴を持ち上げる重い音"}, {"no": 114, "seq": "t1", "local": 82, "scene": "同・屋台前の路地・夜", "start": 680.0, "sec": 6.0, "frames": [], "camera": "FIX", "shot": "LS", "picture": "出汁が扇状に宙を舞う。その向こうでニルの鎖が編み上がり、壁になる。", "action": "出汁は鎖の壁に全部当たって弾ける。仮面には一滴も届かない。", "dialogue": "", "dialogue_en": "", "sound": "【SE】ジュウゥッ（鎖に湯が当たる）"}, {"no": 115, "seq": "t1", "local": 83, "scene": "同・屋台前の路地・夜", "start": 686.0, "sec": 8.0, "frames": [], "camera": "FIX→Q.T.U.", "shot": "FS→CU", "picture": "湯気が路地を白く満たす。ニルの姿が消える。ジンが湯気の中で目を凝らす。Q.T.U. してジンの足首。", "action": "白い湯気の中から灰色の鎖が音もなく伸び、ジンの足首に絡みつく。", "dialogue": "", "dialogue_en": "", "sound": "【BGM】一瞬落ちる→鎖が絡む瞬間に再開"}, {"no": 116, "seq": "t1", "local": 84, "scene": "同・屋台前の路地・夜", "start": 694.0, "sec": 3.0, "frames": [], "camera": "FIX", "shot": "LS", "picture": "ジンが鎖ごと振り回され、路地の壁に叩きつけられる。", "action": "壁に貼られた古い取立日の告知がジンと一緒に剥がれ落ちる。", "dialogue": "", "dialogue_en": "", "sound": "【SE】骨がきしむ音、壁に当たる鈍い音"}, {"no": 117, "seq": "t1", "local": 85, "scene": "同・屋台前の路地・夜", "start": 697.0, "sec": 5.0, "frames": [], "camera": "FIX", "shot": "LS あおり→MS", "picture": "向かいの屋根の上。ツバメ。", "action": "唐辛子粉の袋を振りかぶって投げる。", "dialogue": "ツバメ（屋根の上から）「アニキ！」", "dialogue_en": "\"Bro!\"", "sound": "【SE】瓦を蹴る音、袋が風を切る音"}, {"no": 118, "seq": "t1", "local": 86, "scene": "同・屋台前の路地・夜", "start": 702.0, "sec": 7.0, "frames": [], "camera": "FIX", "shot": "MS→FS", "picture": "ニルは顔も向けずに鎖で袋を弾く。袋が破れ、粉が風下のジンの顔に全部かかる（ギャグ）。弾いた鎖の余波でツバメが足を滑らせ、屋根から転がり落ちる。", "action": "ジンが盛大にくしゃみ。ツバメは樽の陰に落ちて見えなくなる。", "dialogue": "ジン「へっくし！」", "dialogue_en": "\"Achoo!\"", "sound": "【SE】袋が破れる音、くしゃみ、ツバメの転落音（ガタン、樽が転がる）"}, {"no": 119, "seq": "t1", "local": 87, "scene": "同・屋台前の路地・夜", "start": 709.0, "sec": 6.0, "frames": [], "camera": "FIX", "shot": "BS→FS", "picture": "ジン、くしゃみと涙で顔をぐしゃぐしゃにしたまま樽の方を見る。", "action": "這って立ち上がる。", "dialogue": "ジン「ツバメッ！」", "dialogue_en": "\"Tsubame!\"", "sound": ""}, {"no": 120, "seq": "t1", "local": 88, "scene": "同・屋台前の路地・夜", "start": 715.0, "sec": 6.0, "frames": [], "camera": "FIX", "shot": "FS→CU", "picture": "ジン、殴りかかる。鎖の壁に阻まれ、拳が届かない。→CU。", "action": "鎖が腹にめり込む。", "dialogue": "", "dialogue_en": "", "sound": "【SE】鈍い打撃音"}, {"no": 121, "seq": "t1", "local": 89, "scene": "同・屋台前の路地・夜", "start": 721.0, "sec": 3.0, "frames": [], "camera": "FIX", "shot": "FS", "picture": "もう一度殴りかかる。届かない。", "action": "今度は鎖に払われて背中から地面へ。", "dialogue": "", "dialogue_en": "", "sound": "【SE】背中を打つ音"}, {"no": 122, "seq": "t1", "local": 90, "scene": "同・屋台前の路地・夜", "start": 724.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "BS あおり", "picture": "ニル、見下ろす。仮面のスリットの奥は暗く、何も見えない。", "action": "鎖が背後で静かにうねる。", "dialogue": "ニル「借りる力もない者が、なぜ立つ」", "dialogue_en": "\"You can't even borrow power. Why do you keep standing?\"", "sound": ""}, {"no": 123, "seq": "t1", "local": 91, "scene": "同・屋台前の路地・夜", "start": 728.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "BS 俯瞰", "picture": "地面のジン。", "action": "血の混じった唾を吐いて、笑うように。", "dialogue": "ジン「……知るかよ」", "dialogue_en": "\"...Hell if I know.\"", "sound": ""}, {"no": 124, "seq": "t1", "local": 92, "scene": "同・屋台前の路地・夜", "start": 732.0, "sec": 6.0, "frames": [], "camera": "FIX", "shot": "FS→ECU", "picture": "ジン、三度目に立ち上がる。一歩踏み出し、膝から崩れる。→ECU、ジンの頬が石畳につく。", "action": "左腕は投げ出されたまま。印には変化なし（覚醒はS3に取っておく）。", "dialogue": "", "dialogue_en": "", "sound": "【SE】膝が石畳を打つ音。【BGM】ここで落ちる"}, {"no": 125, "seq": "t1", "local": 93, "scene": "同・屋台前の路地・夜", "start": 738.0, "sec": 5.0, "frames": [], "camera": "FIX", "shot": "POV（天地逆）", "picture": "地面に横たわるジンの視界。逆さの世界。鎖に縛られたケイの背中。ケイの頭上に光の頁。", "action": "画面の端が少しにじむ（ジンの意識の揺れ）。", "dialogue": "", "dialogue_en": "", "sound": "【SE】耳鳴り（薄く）"}, {"no": 126, "seq": "t1", "local": 94, "scene": "同・屋台前の路地・夜", "start": 743.0, "sec": 5.0, "frames": [], "camera": "FIX", "shot": "CU", "picture": "光の頁が一枚、また一枚、ニルの帳簿の中に吸い込まれていく。", "action": "帳簿の頁がそれを綴じるように閉じていく。", "dialogue": "", "dialogue_en": "", "sound": "【SE】頁がめくれて閉じる音×3"}, {"no": 127, "seq": "t1", "local": 95, "scene": "同・屋台前の路地・夜", "start": 748.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "ECU", "picture": "頁の中の幼いジン（粉まみれで麺を打っている）。", "action": "端から紙の白さに抜けていき、消える。", "dialogue": "", "dialogue_en": "", "sound": "【SE】紙が擦れる微かな音"}, {"no": 128, "seq": "t1", "local": 96, "scene": "同・屋台前の路地・夜", "start": 752.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "BS（背中越し）", "picture": "ケイの背中越し、わずかに見える横顔。", "action": "振り返らない。", "dialogue": "ケイ「……ジン。ごめんね」", "dialogue_en": "\"...Jin. I'm sorry.\"", "sound": ""}, {"no": 129, "seq": "t1", "local": 97, "scene": "同・屋台前の路地・夜", "start": 756.0, "sec": 4.0, "frames": [], "camera": "FIX→ゆっくりT.U.", "shot": "ECU", "picture": "ジンの瞳。消えていく頁が映り込んでいる。", "action": "音が遠のき、画面の周辺から白くにじみ始める（次シーン「白い帳簿の空間」へのつなぎ。左腕・印の変化は見せない）。", "dialogue": "", "dialogue_en": "", "sound": "【SE】すべての音が水中のように遠のく。【BGM】なし"}, {"no": 130, "seq": "s3", "local": 1, "scene": "ジンの内面・白い帳簿の空間", "start": 760.0, "sec": 9.0, "frames": ["s3-c01.svg"], "camera": "FIX → SLOW T.U.（9秒かけて枠内へ）", "shot": "ELS／上下なし", "picture": "真っ白な無限空間。帳簿の頁が雪のように舞い、どの頁にも赤インクで「−∞」。画面中央にジンが一人、膝を抱えるように丸まって浮いている。手前の頁はピンぼけ（破線）。", "action": "前カットの路地の喧噪から白へカットイン（つなぎ0フレーム）。頁はゆっくり落ちる／横に流れる／上へ昇るものが混在し、重力の向きがない。ジンはわずかに回転しながら漂う。カメラは9秒かけて静かにT.U.", "dialogue": "", "dialogue_en": "", "sound": "MA：前カットの全音を断ち切って完全無音（0.5秒）→ 時計の秒針「チッ…チッ…」のみ。BGMなし"}, {"no": 131, "seq": "s3", "local": 2, "scene": "ジンの内面・白い帳簿の空間", "start": 769.0, "sec": 7.0, "frames": ["s3-c02.svg"], "camera": "FIX（キャラ浮遊のゆっくりした上下）", "shot": "MS", "picture": "浮いたジンの上半身。マフラーが無重力で大きくうねって画面右上へ流れる。左腕の赤い印（−∞）。手前に大きなピンぼけ頁。", "action": "声に反応し、ジンがゆっくり肩越しに画面左を振り返る（首→目の順）。誰もいない。髪とマフラーは水中のように遅れてなびく。", "dialogue": "ハザマ（子どもの声・OFF）「ねえ、ジン」", "dialogue_en": "Hazama (child's voice, O.S.): \"Hey, Jin.\"", "sound": "秒針。ハザマの声は左右どちらからでもなく“頭の中”で鳴る処理（センター定位・リバーブ極小）"}, {"no": 132, "seq": "s3", "local": 3, "scene": "ジンの内面・白い帳簿の空間", "start": 776.0, "sec": 9.0, "frames": ["s3-c03.svg"], "camera": "FIX", "shot": "ECU（左手首〜前腕）", "picture": "ジンの左前腕を画面いっぱいに横位置で。赤い印の罫線模様の中央が、唇のように上下に割れて開き、中から白い光。手首側に「−∞」。", "action": "ハザマの台詞に合わせて印の“口”が開閉（口パク2コマ打ち）。発光パルス2回。周囲の赤い光線が呼吸のように伸び縮みする。", "dialogue": "ジン「……誰だ」\nハザマ「きみの、貸主。……ううん、きみのパパに貸したのは、ぼく」", "dialogue_en": "Jin: \"...Who's there?\"\nHazama: \"Your lender. ...No — I lent to your papa.\"", "sound": "秒針。印が開くたび、湿った紙をめくるような小さなSE"}, {"no": 133, "seq": "s3", "local": 4, "scene": "ジンの内面・白い帳簿の空間", "start": 785.0, "sec": 10.0, "frames": ["s3-c04.svg"], "camera": "FIX／RACK FOCUS（ジン後頭部 → ハザマ）", "shot": "OTS（ジン越し）MS", "picture": "手前にジンの後頭部と肩（黒いシルエット寄り）。奥の空中で、下から昇ってくる赤いインクの滴が集まり、裸足の子どもの形になっていく。顔は帳簿の頁で隠れている。頭上に赤い輪。周りを頁が螺旋状に回る。", "action": "インクの滴が逆再生の雨のように下から上へ昇り、頭→胴→脚の順で形を結ぶ（下半身はまだ滴のまま）。ピントがジンからハザマへ送られる。ハザマの声のタイミングで頁の顔がわずかに傾く。", "dialogue": "ジン「父ちゃんに……？」\nハザマ「パパはね、払わなかったの。ぜーんぶ。だから、きみが続きを持ってる」", "dialogue_en": "Jin: \"My dad...?\"\nHazama: \"Papa didn't pay. Not one bit. So now you're holding the rest.\"", "sound": "秒針。インクの滴が“上へ落ちる”ポタ…ポタ…（逆再生処理）"}, {"no": 134, "seq": "s3", "local": 5, "scene": "ジンの内面・白い帳簿の空間", "start": 795.0, "sec": 7.0, "frames": ["s3-c05.svg"], "camera": "FIX（あおり）／帳簿がゆっくり回転", "shot": "LS", "picture": "空中に浮かぶ巨大な帳簿の見開き。左頁に赤字「赤羽 ■■■ −∞」、右頁に書き足されたばかりの「赤羽ジン −∞」。頁の縁にハザマが腰かけ、大きな筆で赤インクを引いている。画面左、小さなジンが見上げる。頁の端から赤インクが垂れる。", "action": "ハザマ、足をぶらぶらさせながら筆で一行を引き切る。くすくす笑いで肩が揺れる。ジンは視線を帳簿の自分の名前に落とし、すぐに目をそらす。", "dialogue": "ハザマ（くすくす笑って）「ねえ、ジン。払う？」\nジン「……払えるかよ、無限なんて」", "dialogue_en": "Hazama (giggling): \"Hey, Jin. Will you pay?\"\nJin: \"...How am I supposed to pay infinity?\"", "sound": "筆が紙を走るサッという音。秒針"}, {"no": 135, "seq": "s3", "local": 6, "scene": "ジンの内面・白い帳簿の空間", "start": 802.0, "sec": 13.0, "frames": ["s3-c06a.svg", "s3-c06b.svg"], "camera": "QUICK T.U.（6コマ）→ FIX／OTS", "shot": "ECU（ハザマ）→ CU（ジン、ハザマ越し）", "picture": "a：ハザマが急に覗き込み、頁の顔が画面を埋める。頁には子どもの落書きのような赤い笑い口。b：手前にハザマの頁の端、奥にジンの顔。", "action": "a：ハザマが一気に寄る（T.U.と同時に頁が傾く）。落書きの口がにいっと広がる。b：うつむいていたジンが、ゆっくり顔を上げる（あごから上がり、最後に目線が来る）。目に光が戻る。", "dialogue": "ハザマ「じゃあ——踏み倒す？」\n（ジン、顔を上げる）\nハザマ「パパとおなじに。そのかわり、使うたびに、きみのをひとつもらうね」", "dialogue_en": "Hazama: \"Then — skip out on it?\"\n(Jin looks up.)\nHazama: \"Just like Papa. But every time you use it, I get to take one of yours.\"", "sound": "「踏み倒す？」の瞬間だけ秒針が止まる → 完全無音2秒 → 秒針再開"}, {"no": 136, "seq": "s3", "local": 7, "scene": "ジンの内面・白い帳簿の空間", "start": 815.0, "sec": 9.0, "frames": ["s3-c07.svg"], "camera": "FIX", "shot": "MS（真横の2ショット）", "picture": "真横から。左にジン、右に浮かぶハザマ。ジンが赤い印の左腕をまっすぐ差し出し、手のひらを開く。ハザマの小さな指が手首の印に触れ、赤いインクの糸が結ばれる。背景に大きな円（判子の予兆）の点線。", "action": "ジンが迷いなく腕を突き出す（止め絵気味に力強く）。ハザマがそっと指先で触れる。触れた点から赤い火花が散り、インクの糸がジンの手首に巻きつく。舞っていた頁がすべて空中で止まる。", "dialogue": "ジン「何でもいい。持ってけ。ケイを返せ」\nハザマ「やくそく、ね」", "dialogue_en": "Jin: \"Whatever. Take it. Just give Kei back.\"\nHazama: \"It's a promise, then.\"", "sound": "「やくそく、ね」の語尾で秒針が止まる"}, {"no": 137, "seq": "s3", "local": 8, "scene": "ジンの内面・白い帳簿の空間", "start": 824.0, "sec": 6.0, "frames": ["s3-c08a.svg", "s3-c08b.svg"], "camera": "FIX → CAM SHAKE（着地で）→ 白→赤 6コマ", "shot": "LS（あおり）→ 全面", "picture": "a：天から巨大な赤い判子（印面に鏡文字の「零」）がジンの真上に落ちてくる。ジンは小さく見上げる。b：判子が押された瞬間、赤いインクが画面中央から全方向へ一気に広がり、白い空間を塗りつぶす。中央にジンの白いシルエットと判子の輪。", "action": "a：判子が縦の流線を引いて急降下（4コマ）。b：着地と同時に赤が中心から外へ6コマで全面を覆う。縁はしぶきでギザギザ。最後のフレームは全面赤 → 現実へカット。", "dialogue": "", "dialogue_en": "", "sound": "SE：判子を押す「ダンッ」（重く大きく）→ 赤が広がるジュワッという音 → そのまま次カットの低音へつなぐ"}, {"no": 138, "seq": "s3", "local": 9, "scene": "屋台前の路地", "start": 830.0, "sec": 8.0, "frames": ["s3-c09a.svg", "s3-c09b.svg"], "camera": "FIX → PAN UP（手首→首筋）", "shot": "ECU（目）→ MS（あおり）", "picture": "a：路地、夜。ジンの目のECU。開いた瞳孔の中に赤い罫線。b：膝をついて起き上がるジンをあおりで。左腕の赤い印が、肘から肩、首筋、あごへ炎のように這い上がる。奥にニルの背中と、鎖に縛られたケイ、ケイの頭上の光の頁。", "action": "a：まぶたが6コマで開く。瞳孔の赤い罫線がピタッと焦点を結ぶ。b：赤い印が炎の舌のように腕を這い上がる（PANで手首から首まで追う）。肩口で脈打つ赤い輪が2回広がる。ジン、片膝から立ち上がる。", "dialogue": "", "dialogue_en": "", "sound": "SE：低音の脈動（ドクン…ドクン…）。BGM（バトル曲）カットアウト"}, {"no": 139, "seq": "s3", "local": 10, "scene": "屋台前の路地", "start": 838.0, "sec": 3.0, "frames": ["s3-c10.svg"], "camera": "FIX", "shot": "MS（ニル背中越し）", "picture": "ニルの背中を手前に大きく。ニルが肩越しに振り向き、仮面の横スリットがこちら（ジン側）を向く。奥にケイと光の頁、ケイを縛る鎖はニルの袖口から伸びている。画面左から光の筋。", "action": "ニルが首だけをゆっくり振り向く（体は動かない）。動揺は見せないが、鎖が一瞬ゆるむ。", "dialogue": "ニル「……その色は」", "dialogue_en": "Nil: \"...That color...\"", "sound": "低音の脈動のみ"}, {"no": 140, "seq": "s3", "local": 11, "scene": "屋台前の路地", "start": 841.0, "sec": 5.0, "frames": ["s3-c11a.svg", "s3-c11b.svg"], "camera": "FOLLOW（速）→ 寄り・CAM SHAKE", "shot": "LS → CU", "picture": "a：ジンがニルへ一直線に走る。四方（上・左・右・足元）から鎖が先端の刃を向けて襲いかかる。ジンの背後に横の流線、赤い腕が残像の尾を引く。b：一本目が頬をかすめ、二本目が肩に食い込む。ジンは歯を食いしばったまま前へ。", "action": "a：ジン前傾で全力疾走、鎖4本が収束。b：肩に鎖が当たった瞬間インパクト（白抜きの星、破片）。体はスメア2コマで前へ抜け、止まらない。頬に切り傷。", "dialogue": "", "dialogue_en": "", "sound": "SE：鎖の風切り（シュッ×4）→ 頬をかすめる音 → 肩に食い込む鈍い音。ジンの息"}, {"no": 141, "seq": "s3", "local": 12, "scene": "屋台前の路地", "start": 846.0, "sec": 4.0, "frames": ["s3-c12.svg"], "camera": "FIX（ハイスピード 4倍スロー）", "shot": "ECU（手と手首）", "picture": "スローモーション。左からジンの赤い左手が、右から伸びるニルの黒手袋の手首——黒い印の帯——をつかむ。空中に塵が止まって浮いている。足元に止まりかけた鎖。", "action": "4倍スロー。指が一本ずつ手首に巻きつく。接触点から細い放射線（ガラスのひび）。塵がゆっくり漂う。", "dialogue": "", "dialogue_en": "", "sound": "SE：ガラスが割れるような、高く澄んだ音「キィン——」（長めに残響）"}, {"no": 142, "seq": "s3", "local": 13, "scene": "屋台前の路地", "start": 850.0, "sec": 5.0, "frames": ["s3-c13.svg"], "camera": "FIX（インサート）", "shot": "ECU（ニルの手首）", "picture": "つかまれたニルの手首。黒い印が真っ白に抜け、残高の数字に赤い取り消し線。画面右上に赤いカウンター「契約停止 00:03」／CONTRACT SUSPENDED。", "action": "黒い印が、ジンの指の位置から白く“消えて”いく（4コマ）。最後に赤い取り消し線がシュッと入る。同時にカウンターが撮影でイン（2コマで点灯）。", "dialogue": "", "dialogue_en": "", "sound": "SE：印が抜けるサーッという音 → カウンター点灯の電子音1回。以降カウンターの“チッ”は鳴らさない（無音のまま3秒を見せる）"}, {"no": 143, "seq": "s3", "local": 14, "scene": "屋台前の路地", "start": 855.0, "sec": 7.0, "frames": ["s3-c14a.svg", "s3-c14b.svg"], "camera": "FIX（止め）→ FIX", "shot": "LS（やや俯瞰）→ MS（ケイ）", "picture": "a：路地の全景。ジンがニルの手首をつかんでいる。ジンを狙っていた鎖が、刃先をジンの数十センチ手前にしたまま空中でぴたりと止まっている。宙に浮いたままの塵。奥にケイ。b：ケイのMS。縛っていた鎖がゆるんで滑り落ち、頭上の光の頁がばらばらと舞い戻っていく。ケイの目が見開かれる。", "action": "a：全鎖が空中で静止（12コマ止め）、刃先だけかすかに震える。b：鎖がずるりとほどける。光の頁がひらひらとケイの頭の中へ吸い込まれて戻る（逆再生のように）。", "dialogue": "", "dialogue_en": "", "sound": "完全な静寂の中、頁が舞い戻るかすかな紙の音だけ"}, {"no": 144, "seq": "s3", "local": 15, "scene": "屋台前の路地", "start": 862.0, "sec": 5.0, "frames": ["s3-c15.svg"], "camera": "FIX", "shot": "CU（ジンの左腕）", "picture": "止まっていた鎖が向きを変え、ジンの左腕に螺旋状に巻きつく。赤い印に一本、灰色の筋が走る（差し押さえの証）。鎖の端はニルへ伸びている。画面左下でジンが歯を見せて笑う。", "action": "鎖が蛇のように反転し、手首から肩へ6コマで巻き上がる。巻き終わりの瞬間、赤い印の中を灰色の筋が一瞬走って残る。ジンが拳を握る。", "dialogue": "ジン「お前の借り物——三秒だけ、俺が差し押さえる」", "dialogue_en": "Jin: \"Your borrowed power — for three seconds, it's mine. Repossessed.\"", "sound": "鎖が巻きつくジャララッ（ジンの側の音として低く重く）"}, {"no": 145, "seq": "s3", "local": 16, "scene": "屋台前の路地", "start": 867.0, "sec": 4.0, "frames": ["s3-c16.svg"], "camera": "PAN ←（ホイップ）", "shot": "FS", "picture": "ジンが足を踏ん張り、鎖ごと左腕を引く。ピンと張った2本の鎖の先で、ニルの体が地面から浮き、真横にこちらへ引き寄せられる。ニル側に横の流線。", "action": "ジンが体をひねって全身で引く（予備動作2コマ→一気に）。ニルは足が浮き、コートをはためかせて水平に飛んでくる。ホイップPANでジン側へ。", "dialogue": "", "dialogue_en": "", "sound": "鎖が張るビンッ → 風切り"}, {"no": 146, "seq": "s3", "local": 17, "scene": "屋台前の路地", "start": 871.0, "sec": 4.0, "frames": ["s3-c17.svg"], "camera": "FIX", "shot": "CU", "picture": "ジンのCU。手前に大きく、引き絞った右拳。目元に影。奥から引き寄せられてくるニルの仮面。カウンター「00:02」。", "action": "拳を引いたまま一瞬の“溜め”。ジンが台詞を言い切る。ニルの仮面が奥から迫る。", "dialogue": "ジン「払わねえよ。」", "dialogue_en": "Jin: \"I'm not paying.\"", "sound": "MA：全音カット（BGM・SE・環境音すべて無音）。台詞だけがドライに響く"}, {"no": 147, "seq": "s3", "local": 18, "scene": "屋台前の路地", "start": 875.0, "sec": 2.0, "frames": ["s3-c18.svg"], "camera": "FIX → CAM SHAKE（大）", "shot": "ECU（拳と仮面）", "picture": "インパクトフレーム。拳が帳簿の表紙形の仮面にめり込み、仮面に大きな亀裂。黒地に白抜きの集中線、飛び散る破片。カウンター「00:01」。", "action": "白黒反転のインパクトフレーム3連（各2コマ）→ 通常色に戻って亀裂が走る。画面揺れ大。", "dialogue": "", "dialogue_en": "", "sound": "SE：拳が仮面に当たる一撃だけ、最大音量（前カットの無音から一気に）"}, {"no": 148, "seq": "s3", "local": 19, "scene": "屋台前の路地", "start": 877.0, "sec": 6.0, "frames": ["s3-c19a.svg", "s3-c19b.svg"], "camera": "CAM SHAKE → 収まり／FIX（インサート）", "shot": "LS（ジン背中越し）→ ECU（ニルの手首）", "picture": "a：ジンの背中越し。拳を振り抜いた先、ニルが路地の奥へ吹き飛んでいく。集中線、破片。ジンの左腕から鎖が外れて落ちる。カウンター「00:01」。b：地面に落ちたニルの手首。白く抜けていた印に、端から黒がにじんで戻る。カウンター「00:00 契約再開」／CONTRACT RESUMED。", "action": "a：ニルが回転しながら奥へ（ショックで3回バウンド）。鎖はジンの腕からほどけ、ニルの方へ這い戻る。b：黒が両端から8コマで印を満たす。指がぴくりと動く。カウンター消灯（撮影）。", "dialogue": "", "dialogue_en": "", "sound": "吹き飛ぶ風切り・遠くで屋台の残骸が崩れる音 → 印が戻るジジッという音 → カウンター消灯音"}, {"no": 149, "seq": "s3", "local": 20, "scene": "屋台前の路地", "start": 883.0, "sec": 6.0, "frames": ["s3-c20.svg"], "camera": "SLOW T.U.（仮面の亀裂へ）", "shot": "MS（あおり）", "picture": "ゆっくり立ち上がるニル。帽子がわずかにずれ、仮面の亀裂から欠けた部分に片目がのぞく。その目はどこか懐かしいものを見るように、穏やか。", "action": "ニルが膝を伸ばしてゆっくり立つ（ためらいのない、静かな動き）。カメラは亀裂の目へゆっくり寄る。目が一度だけまばたき。", "dialogue": "ニル「〈デフォルト〉……。お前の父親と同じ力だ」", "dialogue_en": "Nil: \"Default... The same power your father had.\"", "sound": "環境音が戻る（遠い夜市のざわめき、低く）"}, {"no": 150, "seq": "s3", "local": 21, "scene": "屋台前の路地", "start": 889.0, "sec": 4.0, "frames": ["s3-c21.svg"], "camera": "FIX", "shot": "MS", "picture": "ジンが前のめりに叫ぶ。左腕の赤い印に灰色の筋が残っている。背景は集中線。", "action": "一歩踏み出して叫ぶ。眉が上がり、怒りより驚きが勝った顔。", "dialogue": "ジン「父ちゃんを知ってんのか！」", "dialogue_en": "Jin: \"You knew my dad?!\"", "sound": "環境音（遠い夜市のざわめき）。ジンの声が路地に反響"}, {"no": 151, "seq": "s3", "local": 22, "scene": "屋台前の路地", "start": 893.0, "sec": 7.0, "frames": ["s3-c22.svg"], "camera": "FIX", "shot": "LS（ジン肩越し）", "picture": "路地の奥、ニルの足元に黒い影だまり。ニルの鎖が影に溶け、ニルの体も腰から下が影に沈んでいる。手前にジンの肩と、灰色の筋の入った赤い腕。", "action": "ニルは振り返らずに台詞。言い終えると鎖が液体のように影へ溶け、ニルはまっすぐ立ったまま2秒で影に沈んで消える。影だまりも縮んで消える。", "dialogue": "ニル「取立は保留する。だが帳簿は閉じない。お前の分も、な」", "dialogue_en": "Nil: \"The collection is on hold. But the ledger stays open. Your page too.\"", "sound": "影に沈む低いうねり → BGM：静かな弦、イン（次シーンへまたぐ）"}, {"no": 152, "seq": "t2", "local": 1, "scene": "底帳・麺屋台「霧島」・屋台跡・夜", "start": 900.0, "sec": 5.5, "frames": [], "camera": "FIX → ゆっくり T.B.", "shot": "LS 俯瞰", "picture": "戦いの跡。屋台の暖簾は裂け、丼と箸が路地一面に散乱。提灯が一つ斜めにぶら下がって揺れる。ニルの消えた路地の奥は闇。宙に残った光の頁が、雪のように降りていく。", "action": "最後の頁がケイの方へ吸い込まれて消える（ケイの記憶が戻った合図）。", "dialogue": "", "dialogue_en": "", "sound": "BGM：静かな弦（前シーンから継続）／SE：屋根から垂れる水滴、提灯の軋み"}, {"no": 153, "seq": "t2", "local": 2, "scene": "底帳・麺屋台「霧島」・屋台跡・夜", "start": 905.5, "sec": 6.0, "frames": [], "camera": "FIX → T.U.", "shot": "FS → BS", "picture": "壊れたカウンターにもたれて座り込むケイ。割烹着の袖が裂け、腕に鎖の痕。左頬の古傷。", "action": "ケイ、自分の手をゆっくり握って開く（記憶を確かめる芝居）。T.U.に合わせて顔を上げ、画面外のジンを認める。", "dialogue": "ケイ「……ジン」", "dialogue_en": "\"...Jin.\"", "sound": "弦継続"}, {"no": 154, "seq": "t2", "local": 3, "scene": "底帳・麺屋台「霧島」・屋台跡・夜", "start": 911.5, "sec": 3.5, "frames": [], "camera": "FOLLOW（左→右）", "shot": "MS", "picture": "画面左からツバメが駆け込む。ゴーグルがずれ、片膝を擦りむいている。", "action": "転びかけ、サンダルが片方脱げても構わず走る。", "dialogue": "ツバメ「ケイさん！」", "dialogue_en": "\"Kei!\"", "sound": "SE：サンダルの足音（片足だけ素足の音に変わる）"}, {"no": 155, "seq": "t2", "local": 4, "scene": "底帳・麺屋台「霧島」・屋台跡・夜", "start": 915.0, "sec": 7.0, "frames": [], "camera": "FIX → T.U.（ジンの膝つきに合わせて寄る）", "shot": "FS → CU", "picture": "路地の中央に立つジン。左腕の赤い印が肩から肘へ引いていく。前髪の赤い一房。首の手ぬぐいは千切れかけ。", "action": "赤いインクが指先から一滴落ちる。ジン、ケイへ歩み寄って膝をつき、顔を覗き込む。笑っているが目が不安。", "dialogue": "ジン「覚えてる？ 俺のこと」", "dialogue_en": "\"You remember me?\"", "sound": "SE：インクの滴が落ちる小さな音"}, {"no": 156, "seq": "t2", "local": 5, "scene": "底帳・麺屋台「霧島」・屋台跡・夜", "start": 922.0, "sec": 3.0, "frames": [], "camera": "FIX", "shot": "CU", "picture": "ケイ、目に涙をためて鼻で笑う。", "action": "", "dialogue": "ケイ「当たり前だろ、バカ」", "dialogue_en": "\"Of course I do, idiot.\"", "sound": ""}, {"no": 157, "seq": "t2", "local": 6, "scene": "底帳・麺屋台「霧島」・屋台跡・夜", "start": 925.0, "sec": 7.0, "frames": [], "camera": "FIX → ゆっくり T.U.", "shot": "MS → BS（ケイの肩ごしナメ）", "picture": "ケイがジンを抱き寄せ、横からツバメが二人にしがみつく。", "action": "ジン、目を丸くし、それから声を出して笑う。T.U.でケイの肩越しのジンの顔へ。笑いがゆっくり引き、視線が遠くなる。", "dialogue": "", "dialogue_en": "", "sound": "SE：ジンの笑い声／弦、温かく持ち上がってから細くなる"}, {"no": 158, "seq": "t2", "local": 7, "scene": "底帳・麺屋台「霧島」・屋台跡・夜", "start": 932.0, "sec": 7.5, "frames": [], "camera": "ゆっくり T.U.", "shot": "CU → ECU", "picture": "ジン、笑顔の名残のまま、左手首の印へ視線を落とす。", "action": "台詞の終わりで目を閉じる（ECU）。", "dialogue": "ジン「……あいつ、父ちゃんと同じ力だって言ってた。父ちゃんも、こうやって——」", "dialogue_en": "\"...He said it's the same power my dad had. My dad, he used to—\"", "sound": "弦、細くなる／目を閉じた瞬間、SE：時計の秒針（白い帳簿の空間と同じ音）を1拍"}, {"no": 159, "seq": "t2", "local": 8, "scene": "底帳・麺屋台「霧島」・屋台跡・夜", "start": 939.5, "sec": 8.0, "frames": [], "camera": "T.U.（男の手 → 顔の位置へ）／回想処理（ザラついた質感・周辺減光）", "shot": "LS あおり → MS（幼いジンの主観）", "picture": "回想。夜市の赤い提灯の列。逆光の中、大きな男がこちらへしゃがみ込む。", "action": "男の大きな手が降りてきて、幼いジンの頭に置かれ、くしゃっと撫でる。カメラは腕を伝って男の顔へ上がっていく。", "dialogue": "", "dialogue_en": "", "sound": "SE：遠い夜市のざわめき（くぐもり）、髪を撫でる布ずれ"}, {"no": 160, "seq": "t2", "local": 9, "scene": "底帳・麺屋台「霧島」・屋台跡・夜", "start": 947.5, "sec": 4.5, "frames": [], "camera": "FIX", "shot": "CU（回想）", "picture": "男の顔——のはずの部分。", "action": "カメラが顔に届いた瞬間、顔の部分だけが帳簿の紙のように真っ白に抜ける。白の上に薄い罫線がにじみ出し、縁が紙のようにめくれる。首から下と手は残ったまま。", "dialogue": "", "dialogue_en": "", "sound": "SE：紙を破る、乾いた音／BGM：弦、ここでカットアウト"}, {"no": 161, "seq": "t2", "local": 10, "scene": "底帳・麺屋台「霧島」・屋台跡・夜", "start": 952.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "ECU → CU", "picture": "現実。ジンの目が開く。", "action": "瞬きを一度。眉を寄せ、もう一度、強く目を閉じる。", "dialogue": "ジン（目を開けて）「……あれ」", "dialogue_en": "\"...Huh?\"", "sound": "無音に近い（遠い水滴のみ）"}, {"no": 162, "seq": "t2", "local": 11, "scene": "底帳・麺屋台「霧島」・屋台跡・夜", "start": 956.0, "sec": 9.0, "frames": [], "camera": "短いカットの積み重ね（各約1.5秒）→ 最後だけ T.B.", "shot": "CU → ECU（回想・連続インサート）", "picture": "回想の断片：①男の眉——傷の線が、消しゴムで消すように白く抜ける ②片目だけ細くなる笑い方——目尻の線が白に溶ける ③顔全体が罫線入りの白い頁になる。", "action": "白が広がるたびにフレームがわずかに跳ねる。最後に“顔の頁”がぺりっと剥がれ、闇の上方へひらひら舞い上がって消える（ハザマの帳簿へ綴じられる暗示）。顔のない男の輪郭だけが残る。", "dialogue": "", "dialogue_en": "", "sound": "SE：紙を破る音×2（だんだん小さく）→ 頁がめくれる小さな音"}, {"no": 163, "seq": "t2", "local": 12, "scene": "底帳・麺屋台「霧島」・屋台跡・夜", "start": 965.0, "sec": 4.5, "frames": [], "camera": "FIX", "shot": "CU", "picture": "現実。ジン、目を開けたまま、どこも見ていない。", "action": "唇だけが動く。", "dialogue": "ジン「顔……どんなだっけ」", "dialogue_en": "\"...What did his face look like?\"", "sound": "無音"}, {"no": 164, "seq": "t2", "local": 13, "scene": "底帳・麺屋台「霧島」・屋台跡・夜", "start": 969.5, "sec": 6.0, "frames": [], "camera": "PAN UP", "shot": "ECU → CU（ジンの肩ごしナメ）", "picture": "ジンの背中に回したケイの腕 → ケイの顔。", "action": "指がこわばり、ジンの作業着をぎゅっとつかむ。PAN UPでケイの顔：目を見開き、痛みをこらえるように閉じる（ケイの過去への伏線。台詞なし）。", "dialogue": "", "dialogue_en": "", "sound": "SE：布をつかむ音"}, {"no": 165, "seq": "t2", "local": 14, "scene": "底帳・麺屋台「霧島」・屋台跡・夜", "start": 975.5, "sec": 3.5, "frames": [], "camera": "FIX", "shot": "ECU", "picture": "ジンの左手首の印。", "action": "印が口のように一度ほころび、赤いインクの小さな文字がふわりと浮いて消える。", "dialogue": "ハザマ（ジンの手首から、小さく）「ごちそうさま」", "dialogue_en": "\"Thanks for the meal.\"", "sound": "SE：子どもの小さな笑い声（ごく小さく）"}, {"no": 166, "seq": "t2", "local": 15, "scene": "底帳・麺屋台「霧島」・屋台跡・夜", "start": 979.0, "sec": 8.0, "frames": [], "camera": "FIX（表情の芝居で保つ）", "shot": "BS", "picture": "ジンの顔。画面手前にツバメの頭をナメる。", "action": "ツバメが見上げて首をかしげる（ハザマの声は聞こえていない）。ジン、笑おうとする。口角は上がるが目が追いつかず、笑顔が途中で止まる。", "dialogue": "", "dialogue_en": "", "sound": ""}, {"no": 167, "seq": "t2", "local": 16, "scene": "底帳・麺屋台「霧島」・屋台跡・夜", "start": 987.0, "sec": 3.0, "frames": [], "camera": "FIX", "shot": "LS 俯瞰", "picture": "瓦礫の中に寄り添う三人、小さく。", "action": "動きなし。", "dialogue": "", "dialogue_en": "", "sound": "【SKIP-PROOF】完全無音3秒（環境音も切る）。幕間を挟まず次カットへジャンプカット"}, {"no": 168, "seq": "t2", "local": 17, "scene": "中層・高層茶房「金魚楼」の窓辺・同時刻（夜）", "start": 990.0, "sec": 7.0, "frames": [], "camera": "FIX（ジャンプカット）→ ゆっくり T.U.", "shot": "ECU", "picture": "画面いっぱいの琥珀色の右目。虹彩の中を細かい数字の列が縦に流れる。T.U.で瞳の映り込みへ：底帳の路地、ジンの拳がニルの仮面に入る瞬間の小さな再生映像。", "action": "数字の流れが一瞬止まり、焦点が合う。琥珀の照準枠が映像の中のジンに重なりロック。", "dialogue": "", "dialogue_en": "", "sound": "SE：静寂を破る硬質な数字のさざめき、照準のロック音／BGM：ミオのテーマ（ミニマルなピアノとクリック音）イン"}, {"no": 169, "seq": "t2", "local": 18, "scene": "中層・高層茶房「金魚楼」の窓辺・同時刻（夜）", "start": 997.0, "sec": 6.0, "frames": [], "camera": "T.B.（目 → 窓辺のミオ全体）", "shot": "MS", "picture": "茶房「金魚楼」の窓辺。金魚鉢を模した丸窓、外に中層の灯り。ミオ（17）が椅子で脚を組む。銀灰色のボブ、右目にかかる前髪をかき上げている。黒い上着を肩に掛け、指先の出た手袋。卓上に冷めた紅茶と閉じた扇子。左手首に琥珀の印。", "action": "ミオ、窓ガラスに指先を当てたまま動かない。", "dialogue": "", "dialogue_en": "", "sound": "BGM継続／SE：遠い中層の雑踏、ガラス越しにくぐもる"}, {"no": 170, "seq": "t2", "local": 19, "scene": "中層・高層茶房「金魚楼」の窓辺・同時刻（夜）", "start": 1003.0, "sec": 5.0, "frames": [], "camera": "T.U.（望遠でズームイン）", "shot": "主観（ミオの〈眼〉）・UI", "picture": "〈眼〉の視界。中層の床の隙間、肋骨の骨組みを抜け、はるか下の底帳の路地へ寄る。琥珀の数値UI：ジンの横に「残高：計測不能」「保有借力：なし」、路地の奥のニルの残像に「取立人／格付けAA」「無力化：3.0s」。", "action": "数値UIが一行ずつタイプされるように表示。ジンの欄だけ数字が定まらずノイズで揺れる。", "dialogue": "", "dialogue_en": "", "sound": "SE：UIのタイプ音"}, {"no": 171, "seq": "t2", "local": 20, "scene": "中層・高層茶房「金魚楼」の窓辺・同時刻（夜）", "start": 1008.0, "sec": 7.0, "frames": [], "camera": "FIX", "shot": "BS", "picture": "ミオの横顔。窓の外の光が頬に落ちる。", "action": "淡々と、だがわずかに早口。", "dialogue": "ミオ「残高、計測不能。保有借力、なし。なのに、AAクラスの取立人を三秒で無力化」", "dialogue_en": "\"Balance: unmeasurable. Borrowed power: none. And yet he took down an AA-class Collector in three seconds.\"", "sound": ""}, {"no": 172, "seq": "t2", "local": 21, "scene": "中層・高層茶房「金魚楼」の窓辺・同時刻（夜）", "start": 1015.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "CU", "picture": "ミオ、上着の内ポケットから目薬を出す。", "action": "首を傾け、右目に一滴。", "dialogue": "", "dialogue_en": "", "sound": "SE：目薬の小さな滴音"}, {"no": 173, "seq": "t2", "local": 22, "scene": "中層・高層茶房「金魚楼」の窓辺・同時刻（夜）", "start": 1019.0, "sec": 4.5, "frames": [], "camera": "FIX", "shot": "主観（ミオの〈眼〉）", "picture": "〈眼〉の視界。", "action": "数字の列がノイズのように崩れ、視界全体がにじむ。UIが一瞬欠ける。", "dialogue": "", "dialogue_en": "", "sound": "SE：数字のさざめきに砂嵐が混じる"}, {"no": 174, "seq": "t2", "local": 23, "scene": "中層・高層茶房「金魚楼」の窓辺・同時刻（夜）", "start": 1023.5, "sec": 5.0, "frames": [], "camera": "PAN DOWN（顔 → 卓上のカップ）", "shot": "CU → INSERT", "picture": "ミオ、瞬きを二度。冷めた紅茶を一口飲み、カップを置く。水面に琥珀の目がゆらゆら映る。", "action": "表情を変えずに不調を隠す（プラント：視力担保。説明台詞なし）。水面の目の中の数字が、ゆっくり元の流れに戻る。", "dialogue": "", "dialogue_en": "", "sound": "SE：カップを置く音"}, {"no": 175, "seq": "t2", "local": 24, "scene": "中層・高層茶房「金魚楼」の窓辺・同時刻（夜）", "start": 1028.5, "sec": 7.5, "frames": [], "camera": "T.U.", "shot": "MS → CU", "picture": "ミオ、扇子を取り、ぱちんと開いて口元を隠す。扇子の上に琥珀の目。", "action": "扇子の陰で口角が上がる。", "dialogue": "ミオ「……ふふ。市場にない銘柄、見つけた」", "dialogue_en": "\"Heh. Found a stock that isn't on the market.\"", "sound": "SE：扇子を開く音／BGM、少し上がる"}, {"no": 176, "seq": "t2", "local": 25, "scene": "中層・高層茶房「金魚楼」の窓辺・同時刻（夜）", "start": 1036.0, "sec": 9.0, "frames": [], "camera": "PAN DOWN → O.L.（夜 → 朝）", "shot": "LS（外観）", "picture": "夜の中層、「金魚楼」の丸窓に小さく灯る琥珀の光。カメラが肋骨の骨組みを伝って下へ。闇の底帳の灯りが溶け、上から朝の光が差し込む肋骨へO.L.。", "action": "時間経過。", "dialogue": "", "dialogue_en": "", "sound": "BGM、余韻を残しフェードアウト／SE：昇降骨の軋みと遠い鐘ひとつ"}, {"no": 177, "seq": "t2", "local": 26, "scene": "肋骨の頂点付近・翌朝", "start": 1045.0, "sec": 6.0, "frames": [], "camera": "FIX", "shot": "LS", "picture": "肋骨の頂点付近。湾曲した巨大な骨の上、朝霧。眼下に縦長の都市。昨日と同じ場所に、ジンが一人、小さく座っている。", "action": "霧がゆっくり流れる。", "dialogue": "", "dialogue_en": "", "sound": "SE：高所の風、遠い昇降骨の軋み／BGM：なし（環境音のみ）"}, {"no": 178, "seq": "t2", "local": 27, "scene": "肋骨の頂点付近・翌朝", "start": 1051.0, "sec": 7.5, "frames": [], "camera": "ゆっくり T.U.", "shot": "MS（横）→ CU", "picture": "ジンの横顔。手ぬぐいの端が風になびく。", "action": "目をこすり、閉じる。自分の眉を指先でなぞる——傷があった場所を確かめるように。", "dialogue": "ジン「眉に……傷。……あったんだよな。たしか」", "dialogue_en": "\"A scar... on his eyebrow. There was one. I think.\"", "sound": ""}, {"no": 179, "seq": "t2", "local": 28, "scene": "肋骨の頂点付近・翌朝", "start": 1058.5, "sec": 6.0, "frames": [], "camera": "FIX → PAN UP", "shot": "FS（ジンの背後から）→ あおり", "picture": "ジンの背中に日傘の影がすっと落ちる。PAN UPで、朝の空を背に日傘をさしたミオ。肩に黒い上着、閉じた扇子。", "action": "", "dialogue": "ミオ「赤羽ジン。格付けZERO」", "dialogue_en": "\"Akaba Jin. Rated ZERO.\"", "sound": "SE：低いヒールの足音、2歩で止まる／風"}, {"no": 180, "seq": "t2", "local": 29, "scene": "肋骨の頂点付近・翌朝", "start": 1064.5, "sec": 6.0, "frames": [], "camera": "FIX", "shot": "MS", "picture": "ジン、座ったまま肩越しに手をひらひら振る。", "action": "途中でちらっとだけ振り返る。", "dialogue": "ジン「どうも、ZEROです。サインならお断り。書いたもん、全部燃えるかもしんねえし」", "dialogue_en": "\"Yep, ZERO. No autographs. Anything I sign might go up in flames.\"", "sound": ""}, {"no": 181, "seq": "t2", "local": 30, "scene": "肋骨の頂点付近・翌朝", "start": 1070.5, "sec": 2.0, "frames": [], "camera": "FIX", "shot": "ECU", "picture": "ミオの右目。前髪の陰で琥珀色に点灯する。", "action": "虹彩を数字が流れ始める。", "dialogue": "", "dialogue_en": "", "sound": "SE：〈眼〉の起動音（短い上昇音）"}, {"no": 182, "seq": "t2", "local": 31, "scene": "肋骨の頂点付近・翌朝", "start": 1072.5, "sec": 4.0, "frames": [], "camera": "回り込み（左→右 約45°）", "shot": "MS", "picture": "ジンの全身の周りに琥珀色の数字のホログラムが浮かぶ。桁の列が体を囲んで回る。", "action": "数字は止まろうとして止まらない。ジン、目の前の数字を手で払う。", "dialogue": "", "dialogue_en": "", "sound": "SE：数字のさざめき、ループ"}, {"no": 183, "seq": "t2", "local": 32, "scene": "肋骨の頂点付近・翌朝", "start": 1076.5, "sec": 7.0, "frames": [], "camera": "FIX", "shot": "主観（ミオの〈眼〉）・UI決め", "picture": "〈眼〉の数値オーバーレイ全面表示。中央にジン。左上「残高 BALANCE：−∞」、右上「勝率 WIN PROB.：未定義 UNDEFINED」。残高欄はスロットのように回り続け、最後に「−∞」で固定。勝率欄は「0.0%…99.9%…」と走ったあと「未定義」で止まり点滅。", "action": "2行目の確定に合わせて台詞。", "dialogue": "ミオ「残高：マイナス無限。勝率：未定義」", "dialogue_en": "\"Balance: negative infinity. Win probability: undefined.\"", "sound": "SE：数値確定の“カチ”2回（残高・勝率）／BGM：ミオのテーマ、イン"}, {"no": 184, "seq": "t2", "local": 33, "scene": "肋骨の頂点付近・翌朝", "start": 1083.5, "sec": 7.5, "frames": [], "camera": "FIX", "shot": "MS（2ショット）", "picture": "ミオとジン。ミオ、前髪越しに琥珀の目で観察する。", "action": "ジン、片眉を上げる。", "dialogue": "ミオ「私の〈眼〉は、この街の誰にでも数字を出す。あなただけが、“計算できない”」／ジン「褒めてんの？」", "dialogue_en": "\"My Eye puts a number on everyone in this city. You're the only one it can't calculate.\" / \"Is that a compliment?\"", "sound": ""}, {"no": 185, "seq": "t2", "local": 34, "scene": "肋骨の頂点付近・翌朝", "start": 1091.0, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "BS", "picture": "ミオ、日傘を閉じる。", "action": "閉じた日傘の先で、とん、と骨を突く。", "dialogue": "ミオ「投資家にとって、計算できないものは二種類。ゴミか、大当たり」", "dialogue_en": "\"To an investor, there are two kinds of things you can't calculate. Trash, or the jackpot.\"", "sound": "SE：日傘の先が骨を叩く音"}, {"no": 186, "seq": "t2", "local": 35, "scene": "肋骨の頂点付近・翌朝", "start": 1095.0, "sec": 7.0, "frames": [], "camera": "FIX", "shot": "MS（2ショット）", "picture": "ミオが金の縁取りの契約書を二本の指で差し出す。ジンは座ったまま。", "action": "", "dialogue": "ミオ「投資契約。私があなたの保証人になる。決済戦のエントリー費、装備、情報、全部こちら持ち。見返りは、勝ち分の四割」", "dialogue_en": "\"An investment contract. I'll be your guarantor. Settlement entry fees, gear, intel — all on me. In return, forty percent of your winnings.\"", "sound": "SE：紙がはためく音"}, {"no": 187, "seq": "t2", "local": 36, "scene": "肋骨の頂点付近・翌朝", "start": 1102.0, "sec": 5.5, "frames": [], "camera": "FIX", "shot": "MS（2ショット・切り返しなし）", "picture": "ジン、契約書ではなくミオの顔を見る。", "action": "テンポよく、間を詰めて。ミオの眉がぴくりと動く。", "dialogue": "ジン「闇金だろ、お前んち」／ミオ「調べたの？」／ジン「ツバメが三十秒で」", "dialogue_en": "\"Your family's a loan shark.\" / \"You checked?\" / \"Tsubame did. Took her thirty seconds.\"", "sound": ""}, {"no": 188, "seq": "t2", "local": 37, "scene": "肋骨の頂点付近・翌朝", "start": 1107.5, "sec": 5.5, "frames": [], "camera": "FIX → PAN（手 → ミオ）", "shot": "INSERT → BS", "picture": "契約書を受け取ったジンの手。", "action": "ざっと目を走らせ、二本指で弾いて突き返す。ミオが受け止める。", "dialogue": "ジン「条件が違う」／ミオ「交渉する気？ 価値ゼロの人が」", "dialogue_en": "\"Wrong terms.\" / \"You want to negotiate? You're worth zero.\"", "sound": "SE：紙を弾く音"}, {"no": 189, "seq": "t2", "local": 38, "scene": "肋骨の頂点付近・翌朝", "start": 1113.0, "sec": 3.5, "frames": [], "camera": "FIX", "shot": "BS あおり", "picture": "ジン、立ち上がる。背後に朝の光。", "action": "", "dialogue": "ジン「価値ゼロだから、失うもんもゼロなんだよ」", "dialogue_en": "\"Worth zero means I've got zero to lose.\"", "sound": "BGM、いったん抜く"}, {"no": 190, "seq": "t2", "local": 39, "scene": "肋骨の頂点付近・翌朝", "start": 1116.5, "sec": 7.5, "frames": [], "camera": "FIX", "shot": "MS", "picture": "ジン、ミオの正面に立ち、指を一本立てる。", "action": "", "dialogue": "ジン「一つ。俺の勝ち分はいらねえ。そのかわり、最初の決済戦の賞金で、真っ先にケイの延滞を払え」", "dialogue_en": "\"One. Keep my share. Instead, out of the prize from my first Settlement, you pay off Kei's overdue debt — first thing.\"", "sound": ""}, {"no": 191, "seq": "t2", "local": 40, "scene": "肋骨の頂点付近・翌朝", "start": 1124.0, "sec": 9.0, "frames": [], "camera": "FIX", "shot": "MS（2ショット）", "picture": "向かい合う二人。", "action": "ミオの返しにかぶせ気味に、ジンが二本目の指を立てる。ミオは扇子で口元を隠して返す。", "dialogue": "ミオ「……あの麺屋の？ 回収見込みゼロよ」／ジン「二つ。俺のために、誰かの担保を取るな。一個もだ」／ミオ「闇金の娘に、それを言う？」", "dialogue_en": "\"...The noodle woman? That's unrecoverable.\" / \"Two. Nobody's collateral gets taken on my account. Not one.\" / \"You're saying that to a loan shark's daughter?\"", "sound": ""}, {"no": 192, "seq": "t2", "local": 41, "scene": "肋骨の頂点付近・翌朝", "start": 1133.0, "sec": 7.5, "frames": [], "camera": "ゆっくり T.U.", "shot": "BS あおり", "picture": "ジン、三本目の指。風で手ぬぐいが大きくなびく。赤い印が一度脈打つ。", "action": "", "dialogue": "ジン「三つ。俺がいつかこの街の帳簿を燃やすとき——お前の帳簿も、一緒に燃える。文句言うなよ」", "dialogue_en": "\"Three. Someday, when I burn this city's books — yours burn with them. No complaints.\"", "sound": "SE：風が強まる"}, {"no": 193, "seq": "t2", "local": 42, "scene": "肋骨の頂点付近・翌朝", "start": 1140.5, "sec": 3.0, "frames": [], "camera": "FIX", "shot": "主観（ミオの〈眼〉）・UI", "picture": "〈眼〉の数値オーバーレイ。ジンの周りの数字が、すべて「？」に裏返る。「残高：？」「勝率：？」。", "action": "パタパタと札が返るように一斉に「？」へ。", "dialogue": "", "dialogue_en": "", "sound": "SE：カウンターの空転音、最後に“カチッ”"}, {"no": 194, "seq": "t2", "local": 43, "scene": "肋骨の頂点付近・翌朝", "start": 1143.5, "sec": 6.5, "frames": [], "camera": "FIX → T.B.", "shot": "CU → BS", "picture": "ミオ、扇子を下ろす。", "action": "目を細め、ゆっくり笑う。", "dialogue": "ミオ「……最悪の条件。リターンの上限なし、リスクの上限もなし」", "dialogue_en": "\"...Terrible terms. No cap on the return. No cap on the risk.\"", "sound": ""}, {"no": 195, "seq": "t2", "local": 44, "scene": "肋骨の頂点付近・翌朝", "start": 1150.0, "sec": 8.0, "frames": [], "camera": "FIX", "shot": "MS（2ショット）", "picture": "ミオ、契約書の条件欄に三行を書き足す。", "action": "", "dialogue": "ジン「乗るのか、乗らねえのか」／ミオ「乗るわ。だって、計算できない株は——上がるときも、計算できないもの」", "dialogue_en": "\"You in or not?\" / \"I'm in. A stock you can't calculate — you can't calculate how high it goes, either.\"", "sound": "BGM：ミオのテーマ、再イン"}, {"no": 196, "seq": "t2", "local": 45, "scene": "肋骨の頂点付近・翌朝", "start": 1158.0, "sec": 5.0, "frames": [], "camera": "FIX", "shot": "INSERT → MS", "picture": "金縁の契約書にミオがさらさらとサイン。ペンをくるりと回してジンへ差し出す。", "action": "ジン、首を振る。", "dialogue": "ジン「紙はいらねえ。握手でいい」", "dialogue_en": "\"No paper. A handshake's enough.\"", "sound": "SE：ペン先の走る音"}, {"no": 197, "seq": "t2", "local": 46, "scene": "肋骨の頂点付近・翌朝", "start": 1163.0, "sec": 4.5, "frames": [], "camera": "FIX", "shot": "INSERT（2ショット・手元）", "picture": "差し出されるジンの左手。手首から肘まで赤い印、手首の内側に「−∞」。そこへ伸びてくるミオの手（指先の出た手袋）。", "action": "ミオの手が、空中で止まる。", "dialogue": "", "dialogue_en": "", "sound": "SE：印の低い脈動"}, {"no": 198, "seq": "t2", "local": 47, "scene": "肋骨の頂点付近・翌朝", "start": 1167.5, "sec": 8.0, "frames": [], "camera": "FIX", "shot": "BS（2ショット）", "picture": "手を引っ込めかけたミオと、平然としたジン。", "action": "", "dialogue": "ミオ「……あなたに触ったら、私の〈眼〉の契約、飛ぶわよね」／ジン「三秒だけな」／ミオ「その三秒、私、何も見えないんだけど」", "dialogue_en": "\"...If I touch you, my Eye's contract gets seized, doesn't it?\" / \"Only for three seconds.\" / \"For those three seconds, I can't see a thing.\"", "sound": ""}, {"no": 199, "seq": "t2", "local": 48, "scene": "肋骨の頂点付近・翌朝", "start": 1175.5, "sec": 6.5, "frames": [], "camera": "FIX", "shot": "MS → INSERT", "picture": "ジン、左手を引っ込め、右手を差し出し直す。", "action": "ミオ、上着のポケットから白いレースの手袋を出し、指先まで覆うようにはめる。一瞬ためらってから、レースの手でジンの右手を握る。", "dialogue": "ジン「じゃあ右手で」", "dialogue_en": "\"Then, right hand.\"", "sound": "SE：レースのこすれる音、握る音"}, {"no": 200, "seq": "t2", "local": 49, "scene": "肋骨の頂点付近・翌朝", "start": 1182.0, "sec": 3.5, "frames": [], "camera": "FIX", "shot": "BS（2ショット）", "picture": "握手する二人。", "action": "ミオ、口元だけで笑う。", "dialogue": "ミオ「契約成立。——ZEROさん」", "dialogue_en": "\"Deal. ...Mr. ZERO.\"", "sound": ""}, {"no": 201, "seq": "t2", "local": 50, "scene": "肋骨の頂点付近・翌朝", "start": 1185.5, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "CU", "picture": "ジン、にっと笑う。前髪の赤い一房が風に揺れる。", "action": "", "dialogue": "ジン「ジンだ。ZEROは、そのうち返す」", "dialogue_en": "\"It's Jin. I'll give ZERO back one of these days.\"", "sound": "BGM：主題歌のインストアレンジ、イン（Eテーマの初出）"}, {"no": 202, "seq": "t2", "local": 51, "scene": "肋骨の頂点付近・翌朝", "start": 1189.5, "sec": 5.5, "frames": [], "camera": "T.B.", "shot": "LS", "picture": "肋骨の頂点に並ぶ二人の小さなシルエット。眼下に縦長の都市、上から朝の光。", "action": "", "dialogue": "", "dialogue_en": "", "sound": "BGM：主題歌インスト、盛り上がる"}, {"no": 203, "seq": "t2", "local": 52, "scene": "麺屋台「霧島」・壊れた屋台の前・昼", "start": 1195.0, "sec": 7.0, "frames": [], "camera": "FIX → T.U.", "shot": "LS → MS", "picture": "底帳の昼。空は見えず、上層の照り返しと薄日。壊れた麺屋台を、ケイとツバメが片づけている。T.U.でツバメ：割れた丼を箒で集める。膝に絆創膏。", "action": "", "dialogue": "", "dialogue_en": "", "sound": "BGM：主題歌インスト継続（音量を下げて）／SE：瓦礫をどかす音、箒、陶器のかけら"}, {"no": 204, "seq": "t2", "local": 53, "scene": "麺屋台「霧島」・壊れた屋台の前・昼", "start": 1202.0, "sec": 6.0, "frames": [], "camera": "FIX", "shot": "FS → INSERT", "picture": "スーツ姿の使いの者（左手首に琥珀の印）がカウンターに封筒を置き、一礼して無言で去る。封筒には琥珀色の封蝋、葛葉家の紋。", "action": "ケイの手が封を切る。", "dialogue": "", "dialogue_en": "", "sound": "SE：革靴の足音、封蝋が割れる音"}, {"no": 205, "seq": "t2", "local": 54, "scene": "麺屋台「霧島」・壊れた屋台の前・昼", "start": 1208.0, "sec": 5.5, "frames": [], "camera": "ゆっくり T.U.", "shot": "INSERT", "picture": "中身の書類：「保証契約書　保証人：葛葉ミオ　債務者：霧島ケイ　支払原資：第一決済戦・賞金」。", "action": "", "dialogue": "", "dialogue_en": "", "sound": ""}, {"no": 206, "seq": "t2", "local": 55, "scene": "麺屋台「霧島」・壊れた屋台の前・昼", "start": 1213.5, "sec": 6.0, "frames": [], "camera": "FIX", "shot": "ECU", "picture": "ケイの左手首。包帯をずらすと、色あせた藍の印。「期日超過：3」の表示。", "action": "「期日超過：3」はそのまま残る（完済にはならない。ショーランナー決定：ケイの期限は第2話でも生きている）。その下に、琥珀色のインクで一行が書き足される：「保証人：葛葉ミオ／支払予定：第一決済戦」。", "dialogue": "", "dialogue_en": "", "sound": "SE：インクが書き込まれるかすかな音"}, {"no": 207, "seq": "t2", "local": 56, "scene": "麺屋台「霧島」・壊れた屋台の前・昼", "start": 1219.5, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "MS", "picture": "ツバメ、背伸びしてケイの手首を覗き込む。", "action": "目を丸くして跳び上がる。", "dialogue": "ツバメ「えっ、うそ、アニキ何したの！？」", "dialogue_en": "\"Wait, what?! What did my big bro do?!\"", "sound": ""}, {"no": 208, "seq": "t2", "local": 57, "scene": "麺屋台「霧島」・壊れた屋台の前・昼", "start": 1223.5, "sec": 4.0, "frames": [], "camera": "FIX", "shot": "BS", "picture": "ケイ、答えずに路地の向こうへ視線を上げる。", "action": "", "dialogue": "", "dialogue_en": "", "sound": ""}, {"no": 209, "seq": "t2", "local": 58, "scene": "麺屋台「霧島」・壊れた屋台の前・昼", "start": 1227.5, "sec": 6.5, "frames": [], "camera": "FIX", "shot": "LS（ケイの主観）", "picture": "路地の奥、中層へ続く長い階段。ジンとミオが並んで上っていく小さな後ろ姿。ミオの日傘。", "action": "", "dialogue": "", "dialogue_en": "", "sound": ""}, {"no": 210, "seq": "t2", "local": 59, "scene": "麺屋台「霧島」・壊れた屋台の前・昼", "start": 1234.0, "sec": 5.5, "frames": [], "camera": "FIX → T.U.（腕へ）", "shot": "MS → ECU", "picture": "ケイ、右手で自分の左腕を袖の上から強く握る。", "action": "握りしめる指。袖口から、古い焼印の端がのぞく。", "dialogue": "", "dialogue_en": "", "sound": ""}, {"no": 211, "seq": "t2", "local": 60, "scene": "麺屋台「霧島」・壊れた屋台の前・昼", "start": 1239.5, "sec": 7.5, "frames": [], "camera": "FIX", "shot": "CU", "picture": "ケイの横顔。左頬の古傷。手前にツバメの頭をナメる。", "action": "ジンの背中を見送ったまま、誰にも聞こえない声で。ツバメが見上げて首をかしげる（聞き取れていない）。", "dialogue": "ケイ（小さく）「……あんたの父親の顔は、あたしが覚えてるよ」", "dialogue_en": "\"...I still remember your father's face. I do.\"", "sound": "BGM、一瞬引く"}, {"no": 212, "seq": "t2", "local": 61, "scene": "麺屋台「霧島」・壊れた屋台の前・昼", "start": 1247.0, "sec": 4.5, "frames": [], "camera": "FOLLOW（階段を上るジンに付ける）", "shot": "FS（ジンの背後から）", "picture": "階段を上るジンの背中。隣にミオの日傘。", "action": "", "dialogue": "", "dialogue_en": "", "sound": "SE：階段を上る足音"}, {"no": 213, "seq": "t2", "local": 62, "scene": "麺屋台「霧島」・壊れた屋台の前・昼", "start": 1251.5, "sec": 6.5, "frames": [], "camera": "FIX", "shot": "ECU", "picture": "ジンの左手首。", "action": "赤い印が一度だけ脈打ち、赤いインクの小さな文字が浮かんでは消える。", "dialogue": "ハザマ（手首から）「ねえ、ジン。つぎは、なにをくれる？」", "dialogue_en": "\"Hey, Jin. What'll you give me next?\"", "sound": "SE：低い脈動1回、子どもの声のくすくす笑い"}, {"no": 214, "seq": "t2", "local": 63, "scene": "麺屋台「霧島」・壊れた屋台の前・昼", "start": 1258.0, "sec": 5.0, "frames": [], "camera": "FIX", "shot": "CU", "picture": "ジン、前を見たまま。", "action": "ニッと笑う。", "dialogue": "ジン（前を見たまま、笑って）「払わねえよ」", "dialogue_en": "\"I'm not paying.\"", "sound": ""}, {"no": 215, "seq": "t2", "local": 64, "scene": "麺屋台「霧島」・壊れた屋台の前・昼", "start": 1263.0, "sec": 7.0, "frames": [], "camera": "PAN UP", "shot": "LS", "picture": "階段から肋骨の骨組みを伝い、上層の光へ。", "action": "二人の姿が小さくなり、光の中へ。", "dialogue": "", "dialogue_en": "", "sound": "BGM：主題歌インスト、最高潮 → ジャストでカットアウト（TAGへ）"}, {"no": 216, "seq": "s4", "local": 1, "scene": "頂・取引所〈バース〉頭取室・夜", "start": 1270.0, "sec": 6.0, "frames": ["s4-c01a.svg", "s4-c01b.svg"], "camera": "FIX → PAN R（ゆっくり）", "shot": "LS", "picture": "白い大理石の頭取室。壁一面の〈公開格付け〉スクリーン（AAA→Dの名前の列）。床の大理石にスクリーンの光が映る。PAN 終わりで大きな窓と、窓辺で紅茶をいれる九条レイジ（白の三つ揃い・白手袋・杖）。窓外は夜の底帳の灯と、死んだ神の肋骨の弧。", "action": "スクリーンの名前がゆっくり下から上へ流れ続ける（ROLL）。PAN で壁の画面から窓辺の九条へ。九条は背筋を伸ばしたまま、カップに紅茶を注いでいる。最下段の赤い「ZERO」はこのカットでは小さく、まだ点いているだけ（強調しない）。", "dialogue": "", "dialogue_en": "", "sound": "BGM：弦楽四重奏（静かに IN）／SE：スクリーンの微かなハム音"}, {"no": 217, "seq": "s4", "local": 2, "scene": "頂・取引所〈バース〉頭取室・夜", "start": 1276.0, "sec": 5.0, "frames": ["s4-c02.svg"], "camera": "FIX", "shot": "MS（やや あおり）", "picture": "窓を背にした九条の腰上。金縁眼鏡、撫でつけた髪、柔らかな笑顔。手前のサイドテーブルでポットからカップへ紅茶を注ぐ。窓外遠景に肋骨の弧と下層の灯。画面左端は大理石の壁とスクリーンの照り返し。", "action": "白手袋の手でポットを傾け、紅茶の細い流れ。湯気が立つ。表情は変わらない（完璧な笑顔のまま）。", "dialogue": "", "dialogue_en": "", "sound": "SE：注ぐ音、陶器の小さな音／BGM 継続"}, {"no": 218, "seq": "s4", "local": 3, "scene": "頂・取引所〈バース〉頭取室・夜", "start": 1281.0, "sec": 10.0, "frames": ["s4-c03a.svg", "s4-c03b.svg"], "camera": "PAN DOWN（6秒）→ T.U.（4秒）", "shot": "INSERT（スクリーン）→ ECU", "picture": "スクリーンのインサート。上段は「公開格付け PUBLIC RATINGS」と AAA・AA・A・B の名前と数値（濃い文字）。下へ行くほど C・D と文字が灰色に薄れ、名前のない灰色の空行が続く。そのさらに下、暗い最下段に一行だけ赤い「ZERO」。名前は出さない（文字は ZERO のみ）。", "action": "数百万の名前が流れる中を、カメラが最上段から最下段まで PAN DOWN。灰色の列を抜けた先で止まり、赤い ZERO に T.U.。ZERO は不安定にちらつく（点・滅・点の3回、横に走るノイズ）。", "dialogue": "", "dialogue_en": "", "sound": "BGM 継続（チェロが一音だけ低く残る）／SE：ちらつきの電気ノイズ（小）"}, {"no": 219, "seq": "s4", "local": 4, "scene": "頂・取引所〈バース〉頭取室・夜", "start": 1291.0, "sec": 7.0, "frames": ["s4-c04a.svg", "s4-c04b.svg"], "camera": "FIX", "shot": "BS", "picture": "九条のバスト。窓の夜景を背に、左（スクリーン側）から白い光。A：目を閉じて紅茶を一口。B：カップをソーサーに置き、目を開けて画面左外（スクリーン）を見る。眼鏡のレンズに赤い ZERO の小さな映り込み。", "action": "一口飲む（A）→ ゆっくりカップを下ろし、ソーサーに置く（B）。視線だけが画面左外のスクリーンへ。手袋は外さない。", "dialogue": "", "dialogue_en": "", "sound": "SE：カップがソーサーに当たる小さな音（BGM が一瞬引く）"}, {"no": 220, "seq": "s4", "local": 5, "scene": "頂・取引所〈バース〉頭取室・夜", "start": 1298.0, "sec": 4.0, "frames": ["s4-c05.svg"], "camera": "FIX", "shot": "O.S.（肩なめ）", "picture": "九条の後頭部と右肩を手前に大きくなめて、正面の巨大スクリーン。灰色の名前の列が奥へパースで流れ、最下段で赤い ZERO が小さくちらつく。", "action": "九条は動かずスクリーンを見ている。ZERO だけが点滅を続ける。", "dialogue": "", "dialogue_en": "", "sound": "BGM 継続（音数を減らす）"}, {"no": 221, "seq": "s4", "local": 6, "scene": "頂・取引所〈バース〉頭取室・夜", "start": 1302.0, "sec": 8.0, "frames": ["s4-c06.svg"], "camera": "FIX → ゆっくり T.U.（約10%）→ C.O.（暗転）", "shot": "CU（正面）", "picture": "九条の顔の正面。左からスクリーンの白い光、右半分は窓側の暗がり。目を細めた優しい微笑み。眼鏡の両レンズに赤い ZERO の映り込み。", "action": "ゆっくり T.U. しながら、九条が赤い一行に向かって優しく微笑む。台詞のあと一拍。判子の音と同時にカットアウトで暗転（黒）。笑顔以外の芝居はしない（手袋・印・正体には触れない）。", "dialogue": "九条「……おかえり、赤羽」", "dialogue_en": "\"Welcome back, Akaba.\"", "sound": "BGM：台詞前で止める／SE：判子を押す音 → 暗転（無音1拍）"}, {"no": 222, "seq": "s4", "local": 7, "scene": "次回予告・タイトルカード", "start": 1310.0, "sec": 5.0, "frames": ["s4-c07.svg"], "camera": "あおり／TILT UP（ゆっくり）", "shot": "LS（あおり）", "picture": "黒画面からの次回映像（ED一体型・上下黒帯）。昇降骨の内部を真下から見上げる。骨の輪が同心円状に重なり、はるか上に白い光。輪をよじ登るジン（逆立つ髪・首巻きの端がはためく・左手首に赤い印）と、その下のミオ（ボブ髪・肩掛けの上着）のシルエット。", "action": "黒画面にミオの声 → 映像 IN。ジンが上の輪をつかんで体を引き上げ、ミオが続く。カメラはゆっくり TILT UP。", "dialogue": "ミオ（V.O.）「次回、昇降骨を登って中層へ。取立人に捕まる確率、87％」", "dialogue_en": "Mio (V.O.): \"Next time: up the Lift Bone to the mid-tier. Odds of getting caught by a Collector: 87%.\"", "sound": "予告BGM（ED曲のイントロ）IN／SE：骨がきしむ音、反響"}, {"no": 223, "seq": "s4", "local": 8, "scene": "次回予告・タイトルカード", "start": 1315.0, "sec": 4.0, "frames": ["s4-c08.svg"], "camera": "手持ち", "shot": "BS（やや俯瞰）", "picture": "斜めに走る骨の段にしがみつくジン。肩越しにこちら（下）を振り返り、にやりと笑う。左腕に赤い印。はるか下の暗がりに、平たいつばの制帽と帳簿形の仮面（横一本のスリット）のニルが小さく立ち、見上げている。", "action": "ジンが下を見て、口の端を上げる。ニルは動かない（顔は見せすぎない、遠景の小ささで）。", "dialogue": "ジン（V.O.）「じゃあ残りの13％、全部もらうわ」", "dialogue_en": "Jin (V.O.): \"Then I'll take the other 13%. All of it.\"", "sound": "予告BGM 継続"}, {"no": 224, "seq": "s4", "local": 9, "scene": "次回予告・タイトルカード", "start": 1319.0, "sec": 5.0, "frames": ["s4-c09.svg"], "camera": "FIX", "shot": "CU", "picture": "ミオの顔のアップ。右目は前髪で隠れ、見えている左目の横に〈眼〉の読み取り表示「87%」（色付けでは琥珀）。手前に扇子。背景は昇降骨内部の暗い輪。", "action": "ミオは無表情のまま扇子越しに問う。直後、ジンの即答に、ミオの目がわずかに細くなる（あきれ）。", "dialogue": "ミオ（V.O.）「あなたが逃げ切る確率は？」／ジン（V.O.）「未定義！」", "dialogue_en": "Mio (V.O.): \"And your odds of getting away?\" / Jin (V.O.): \"Undefined!\"", "sound": "予告BGM、ジンの「未定義！」でブレイク"}, {"no": 225, "seq": "s4", "local": 10, "scene": "次回予告・タイトルカード", "start": 1324.0, "sec": 6.0, "frames": ["s4-c10.svg"], "camera": "FIX", "shot": "タイトルカード", "picture": "黒地に帳簿の罫線。中央に「第2話」と大きく「投資契約」、下に英題 Episode 2: \"Terms and Conditions\"。右下に判子の押し跡（無彩色）。", "action": "黒からタイトルがカットイン。判子の音で押し跡が入り、そのまま終わり（F.O. なし、カットアウト）。", "dialogue": "", "dialogue_en": "", "sound": "SE：判子。終わり（BGM 同時に切る）"}]};
